INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Anestesi Epidural', 'Anestesi Obstetrik', 17,
  'Seorang pasien inpartu membutuhkan penanganan nyeri persalinan. Dokter penanggung jawab telah memutuskan untuk melakukan anestesi epidural.', 'Lakukan evaluasi pra-anestesi, berikan edukasi dan informed consent kepada pasien, serta lakukan tindakan anestesi epidural pada manekin.',
  'Amati dan nilai peserta ujian dalam melakukan evaluasi pra-anestesi, komunikasi edukasi dan profesionalisme, serta keterampilan klinis dalam tindakan anestesi epidural sesuai rubrik yang disediakan.', ARRAY['Manekin simulasi tindakan epidural', 'Set epidural steril', 'Obat anestesi lokal (misalnya Lidokain, Bupivakain)', 'Antiseptik kulit', 'Sarung tangan steril', 'Masker dan topi', 'Alat monitoring tanda vital'], '[{"aspect": "Evaluasi Pra Anestesia", "weight": 2, "items": ["Anamnesis", "Pemeriksaan fisik lain", "Pemeriksaan penunjang"]}, {"aspect": "Komunikasi edukasi dan Profesionalisme", "weight": 3, "items": ["Melakukan edukasi dan informed consent dengan lengkap meliputi: Prosedur, Manfaat, Risiko, Komplikasi, Alternatif", "Meminta izin secara lisan", "Melakukan setiap tindakan dengan berhati-hati dan teliti sehingga tidak membahayakan pasien dan diri sendiri", "Memperhatikan kenyamanan pasien", "Melakukan tindakan sesuai prioritas", "Menunjukkan rasa hormat kepada pasien", "Mengetahui keterbatasan dengan merujuk atau melakukan konsultasi bila diperlukan"]}, {"aspect": "Keterampilan klinis", "weight": 4, "items": ["Mampu melakukan tindakan epidural anestesi secara lengkap"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Luka Bakar - CVC', 'Anestesi Umum & Regional', 17,
  'Seorang Laki-laki 52 tahun, berat badan 50 kg, korban kebakaran 4 jam yang lalu di konsulkan ke ruang resusitasi. Pada pemeriksaan tidak didapatkan tanda tanda trauma inhalasi. Luka bakar 60% di regio abdominal dan ekstremitas bawah', 'Sampaikan pada penguji rencana resusitasi cairan menurut rumus Parkland!
Lakukan tindakan pemasangan kateter vena sentral!',
  'Penguji menilai rencana resusitasi cairan menurut rumus Parkland yang disampaikan peserta, meliputi:
- Jumlah Cairan : 4 x 50 x 60 = 12000 ml
- Jenis Cairan : kristaloid
- Cara Pemberian cairan : 8 jam pertama : 6000 ml / 8 jam sejak jam kejadian, 8 jam kedua : 3000 ml / 8 jam, 8 jam ketiga : 3000 ml / 8 jam.

Penguji menilai prosedur pemasangan kateter vena sentral yang dilakukan peserta ujian, meliputi:
- Mempersiapkan alat cvc set, tiang infus, ambu bag, obat emergensi
- Memberikan salam, memperkenalkan diri dan menjelaskan tindakan yang akan dilakukan
- Memasang alat monitor pada pasien dan monitor tanda-tanda vital pasien
- Identifikasi marker
- Cuci Tangan dan memakai sarung tangan Steril
- Desinfeksi area yang sudah diidentifikasi
- Pemasangan kain steril bolong
- Dilakukan anestesi lokal pada area cvc
- Penusukan jarum CVC sambil dilakukan aspirasi
- Aspirasi (+) dilakukan pemasangan guidewire
- Jarum CVC dicabut kemudian dimasukan dilator
- Dilator dicabut kemudian insersi cvc sampai kedalaman yang telah ditentukan
- Tes aspirasi (+), tes aliran balik (+)
- Fiksasi dengan jahitan dan tutup dengan kassa steril
- Mencuci tangan
- Permintaan foto thoraks setelah pemasangan cvc.

Penguji menilai penjelasan peserta pada pasien tentang:
- Tindakan: Pemasangan kateter vena sentral
- Manfaat: akses intra vena besar, mengukur kecukupan cairan
- Resiko: perdarahan, pneumothorax, gangguan irama jantung
- Efek samping: nyeri lokasi penusukan, infeksi
- Alternatif tindakan : akses infus perifer.', ARRAY['Manekin CVC', 'CVC set', 'Tiang infus', 'Ambu bag', 'Obat emergensi', 'Hekting set', 'Cairan infus', 'Infus set', 'Alat monitoring tanda vital', 'Sarung tangan steril', 'Antiseptik kulit', 'Kain steril bolong', 'Obat anestesi lokal', 'Kassa steril'], '[{"aspect": "Rencana tindakan Anestesi", "weight": 3, "items": ["Mampu menyampaikan rencana resusitasi dengan tepat yang meliputi item: Jumlah cairan", "Mampu menyampaikan rencana resusitasi dengan tepat yang meliputi item: Jenis cairan", "Mampu menyampaikan rencana resusitasi dengan tepat yang meliputi item: Cara pemberian"]}, {"aspect": "Keterampilan klinis", "weight": 4, "items": ["Mempersiapkan alat cvc set, tiang infus, ambu bag, obat emergensi", "Memasang alat monitor pada pasien dan monitor tanda-tanda vital pasien", "Identifikasi marker", "Cuci Tangan dan memakai sarung tangan Steril", "Desinfeksi area yang sudah diidentifikasi", "Pemasangan kain steril bolong", "Dilakukan anestesi lokal pada area cvc", "Penusukan jarum CVC sambil dilakukan aspirasi", "Aspirasi (+) dilakukan pemasangan guidewire", "Jarum CVC dicabut kemudian dimasukan dilator", "Dilator dicabut kemudian insersi cvc sampai kedalaman yang telah ditentukan", "Tes aspirasi (+)", "Tes aliran balik (+)", "Fiksasi dengan jahitan dan tutup dengan kassa steril", "Mencuci tangan (setelah tindakan)", "Permintaan foto thoraks setelah pemasangan cvc"]}, {"aspect": "Komunikasi, Edukasi Dan Profesionalisme", "weight": 3, "items": ["Memberikan salam, memperkenalkan diri dan menjelaskan tindakan yang akan dilakukan", "Menjelaskan Tindakan: Pemasangan kateter vena sentral", "Menjelaskan Manfaat: akses intra vena besar, mengukur kecukupan cairan", "Menjelaskan Resiko: perdarahan, pneumothorax, gangguan irama jantung", "Menjelaskan Efek samping: nyeri lokasi penusukan, infeksi", "Menjelaskan Alternatif tindakan: akses infus perifer"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Manajemen Anestesi Pada Pasien dengan Penyulit Mitral Severe - INTUBASI', 'Anestesi Kardiovaskular', 17,
  'Seorang laki-laki 43 tahun akan direncanakan tindakan operasi elektif multiple odontektomi dengan berat badan 65 kg TB: 170 cm. Pasien memiliki riwayat kontrol rutin ke dokter jantung dengan diagnosa Mitral Stenosis severe dan hendak cabut gigi untuk persiapan operasi jantung. Pasien direncanakan operasi dengan general anestesi, intubasi endotrakeal.', '1. Lakukan Evaluasi Pra Anestesia!
2. Jelaskan prinsip manajemen anestesi intraoperatif pada pasien ini!
3. Lakukan intubasi pada pasien ini !
4. Lakukan tatalaksana penyulit yang muncul pada tindakan anestesi pasien ini!',
  'INSTRUKSI UMUM:
1. Pastikan identitas peserta ujian pada kartu ujian
2. Tulislah nama dan nomor peserta ujian pada lembar penilaian!
3. Amatilah dan berilah skor (0/1/2/3) atas tugas yang dikerjakan peserta ujian serta skor Global Rating sesuai rubrik penilaian.
4. Hindarilah interupsi dan/atau tindakan selain daripada yang diminta dalam instruksi penguji!
5. Berikan informasi/ hasil yang dibutuhkan secara lisan/ tulisan hanya apabila peserta ujian telah melakukan dan/ atau mengusulkan jenis pemeriksaan yang dimaksud (perhatikan instruksi khusus)!
6. Taatilah peraturan serta etika penguji selama menjalankan tugas sebagai penguji OSCE - ATI!

INSTRUKSI KHUSUS:
1. Evaluasi Pra Anestesi yang harus dilakukan peserta:
A. Anamnesis:
Subyektif: Pasien dengan keluhan sering sesak napas dan merasa mudah lelah. Jantung terasa berdebar-debar. Pasien tidak sanggup berjalan naik tangga ke lantai 2. Pasien masih sanggup melakukan aktivitas ringan sehari-hari.
AMPLE:
Alergi Disangkal
Medication - mecobalamin 2x500 mcg - warfarin 1x4 mg (sudah berhenti 1 minggu yll), - candesartan 1x8 mg, - bisoprolol 1x10 mg
Past illness stroke (-), HT (-), DM (-), Asma (-), Riw. Op (-)
Last meal Persiapan puasa elektif
Event Pasien dengan keluhan nyeri gigi bagian belakang kiri atas dan bawah sejak 3 bulan yang lalu
B. Pemeriksaan Fisik
1. Tanda Vital TD : 119/79 mmHg, HR 70 bpm, RR 20 x/menit, T : 36.7 C, VAS : 3, SpO2 95% room air (supine), BB 65 kg, TB : 170 cm, BMI 22.4kg/m2 (normal)
2. Pemeriksaan head to toe : dalam batas normal, kecuali pada sistem kardiovaskular, ditemukan murmur diastolik
3. Evaluasi jalan napas dengan LEMON dalam batas normal
4. Periksa kondisi gigi-geligi : gigi goyang (-), impaksi 2.8 dan 3.8
5. Periksa patensi lubang hidung dan ada tidaknya deviasi septum hidung à lobang hidung paten tanpa deviasi
C. Pemeriksaan Penunjang
1. Laboratorium : dalam batas normal
2. Ro Thoraks : kardiomegali dengan double right heart border (Penguji memperlihatkan gambar rontgen thorax)
3. EKG : Atrial Fibrilasi Normal Ventrikular Respon (penguji memperlihatkan gambaran EKG)
4. Echocardiography : - Aorta : AR mild - Mitral : MS Severe - Trikuspid : TR Moderate - Pulmonal: PR Mild, Low probability of PH - Thrombus (-) intrakardiak - Kesimpulan: Kontraktilitas LV menurun dengan EF 35 % Menyokong Penyakit Jantung Rheumatik dengan MS severe, MR Mild, AR Mild, PR Mild, TR Moderate, low probability of PH

2. Prinsip manajemen anetesi intraoperatif pada pasien ini
1) Preload: maintain (avoid overload)
2) Rate: low-normal (most important goal)
3) Rhythm: sinus (avoid atrial fibrillation rapid response)
4) Contractility: maintain
5) Afterload: maintain
6) Avoid precipitants of pulmonary hypertension (asidosis, atelektasis, hipercarbia, hipotermia, hipoksemia, stress response : nyeri, light sedasi)
7) Persiapkan obat-obat untuk penanganan hipotensi, seperti phenylephrine dan vasopressin

3. Menilai tindakan anestesi pada pasien ini :
Penguji memperlihatkan setting monitor awal sebagai berikut : Tekanan darah : 115/ 60 mmHg Denyut jantung : 72 kali/menit Saturasi O2 : 95 % dengan udara ruangan Suhu : 37,1oC
1) Peserta memakai sarung tangan non steril
2) Peserta menyiapkan peralatan intubasi (STATICS) • Scope: laryngoscope dan stetoscope • Tube: ETT dengan 3 ukuran (6,5/7/7,5) • Airway: Oropharyngeal airway • Tapes • Introducer • Connector • Suction berfungsi baik
3) Siapkan peralatan airway lengkap
4) Pasang monitor ke pasien (TD, Saturasi, EKG, Suhu, ETCO2)
5) Harus dilakukan preoksigenasi oksigen 100% selama 3-5 menit
6) Memberikan obat hipnotik-sedatif untuk induksi dengan agen intravena yang dititrasi perlahan, tidak menyebabkan peningkatan denyut jantung dan penurunan SVR yang signifikan: midazolam 0.01-0.15mg/kg, fentanyl 1-2 mcg/kg dosis titrasi, ketamin 0.1-0.5 mg/kg dosis titrasi, propofol 1-2 mg/kgBB dosis titrasi.
7) Memberikan oksigenasi dengan ventilasi tekanan positif O2 100% selama 3 – 5 menit
8) Setelah airway terkuasai, berikan pelumpuh otot Atracurium 0.5 mg/kg titrasi atau Rocuronium 0.6-1.2 mg/kgBB
9) Setelah onset tercapai, lakukan intubasi dengan smooth, pastikan kedalaman ETT, dan lakukan fiksasi ETT
10) Pasang ETCO2 untuk pemantauan

4. Menilai tatalaksana penyulit yang muncul pada tindakan anestesi pasien ini :
Penguji menyampaikan skenario setelah pasien terintubasi : Penguji memperlihatkan perubahan hemodinamik pada monitor sebagai berikut : Tekanan darah : 85/50 mmHg Denyut jantung : 125 kali/menit Saturasi O2 : 92 % dengan O2 100%
Tindakan yang harus dilakukan peserta :
1. Menurunkan frekuensi denyut jantung dengan pemberian analgetik (fentanyl) sebagai antisipasi penyebab stimulus simpatis saat intubasi,
2. Meningkatkan tekanan darah menggunakan obat vasopressor seperti phenylephrine 50-250 mcg intravena,
Jika peserta melakukan kedua tindakan di atas, selanjutnya penguji memperlihatkan perubahan monitor sebagai berikut : Tekanan darah : 95/60 mmHg Denyut jantung : 110 kali/menit Saturasi O2 : 94 % dengan O2 100%
Selanjutnya peserta melakukan :
3. Menurunkan frekuensi denyut jantung dengan pemberian beta blocker intravena (metoprolol injeksi dosis 2,5-10 mg)
Jika peserta melakukan tindakan di atas, selanjutnya penguji memperlihatkan perubahan monitor sebagai berikut : Tekanan darah : 110/60 mmHg Denyut jantung : 78 kali/menit Saturasi O2 : 96 % dengan O2 100%', ARRAY['Meja dan kursi dokter (1 set)', 'Meja dan kursi penguji (1 set)', 'Meja peralatan (1 buah)', 'Meja operasi (1 buah)', 'Manekin (1 buah)', 'Stetoskop (1 buah)', 'Monitor Pasien (1 buah)', 'Monitor End Tidal CO2 (1 buah)', 'Stylet (1 buah)', 'Laringoskop blade 3, 4 (@1 buah)', 'Suction no 12, 14 (@1 buah)', 'Sungkup Muka no 3, 4, 5 (@1 buah)', 'Ambu bag (1 buah)', 'ETT 7,5/ 7/ 6.5 (@1 buah)', 'Plester (1 buah)', 'Mesin anestesi dengan ventilator (1 buah)', 'Midazolam (1 ampul)', 'Fentanyl (1 ampul)', 'Propofol (1 ampul)', 'Atracurium (1 ampul)', 'Rocuronium (1 ampul)', 'Prostigmin (1 ampul)', 'Naloxone (1 ampul)', 'Sulfas Atropine (1 ampul)', 'Adrenalin (1 ampul)', 'Phenylephrine (1 ampul)', 'Metoprolol (1 ampul)', 'Sarung tangan non steril (1 kotak)', 'Videolaringoskope (1 buah)', 'LMA 4 dan 5 (@1 buah)', 'Oropharyngeal airway 90/100 mm (@ 1 buah)', 'Suction kanul 12/14 F (@ 1 buah)', 'Tempat sampah tertutup (1 buah)', 'Jam dinding (1 buah)', 'Wastafel (1 buah)', 'Ipad atau tablet android untuk monitor pasien (1 buah)'], '[{"aspect": "Evaluasi Pra operasi", "weight": 2, "items": ["Anamnesis dan AMPLE lengkap", "Pemeriksaan Fisik (tanda vital) lengkap", "Pemeriksaan penunjang lengkap"]}, {"aspect": "Prinsip manajemen intraoperatif", "weight": 2, "items": ["Preload: maintain (avoid overload)", "Rate: low-normal (most important goal)", "Rhythm: sinus (avoid atrial fibrillation rapid response)", "Contractility: maintain", "Afterload: maintain", "Avoid precipitants of pulmonary hypertension (asidosis, atelektasis, hipercarbia, hipotermia, hipoksemia, stress response : nyeri, light sedasi)", "Persiapkan obat-obat untuk penanganan hipotensi, seperti phenylephrine dan vasopressin"]}, {"aspect": "Rencana Tindakan Anestesi", "weight": 2, "items": ["Peserta memakai sarung tangan non steril", "Peserta menyiapkan peralatan intubasi (STATICS): Scope (laryngoscope dan stetoscope), Tube (ETT dengan 3 ukuran (6,5/7/7,5)), Airway (Oropharyngeal airway), Tapes, Introducer, Connector, Suction berfungsi baik", "Siapkan peralatan airway lengkap", "Pasang monitor ke pasien (TD, Saturasi, EKG, Suhu, ETCO2)", "Harus dilakukan preoksigenasi oksigen 100% selama 3-5 menit", "Memberikan obat hipnotik-sedatif untuk induksi dengan agen intravena yang dititrasi perlahan, tidak menyebabkan peningkatan denyut jantung dan penurunan SVR yang signifikan: midazolam 0.01-0.15mg/kg, fentanyl 1-2 mcg/kg dosis titrasi, ketamin 0.1-0.5 mg/kg dosis titrasi, propofol 1-2 mg/kgBB dosis titrasi.", "Memberikan oksigenasi dengan ventilasi tekanan positif O2 100% selama 3 – 5 menit", "Setelah airway terkuasai, berikan pelumpuh otot Atracurium 0.5 mg/kg titrasi atau Rocuronium 0.6-1.2 mg/kgBB", "Setelah onset tercapai, lakukan intubasi dengan smooth, pastikan kedalaman ETT, dan lakukan fiksasi ETT", "Pasang ETCO2 untuk pemantauan"]}, {"aspect": "Monitoring dan Manajemen Penyulit", "weight": 3, "items": ["Menurunkan frekuensi denyut jantung dengan pemberian analgetik (fentanyl) sebagai antisipasi penyebab stimulus simpatis saat intubasi", "Meningkatkan tekanan darah menggunakan obat vasopressor seperti phenylephrine 50-250 mcg intravena", "Menurunkan frekuensi denyut jantung dengan pemberian beta blocker intravena (metoprolol injeksi dosis 2,5-10 mg)"]}, {"aspect": "Komunikasi, edukasi dan profesionalisme", "weight": 1, "items": ["Memperkenalkan diri kepada pasien", "Melakukan setiap tindakan dengan berhati-hati dan teliti sehingga tidak membahayakan pasien dan diri sendiri", "Memperhatikan kenyamanan pasien", "Melakukan tindakan sesuai prioritas", "Melakukan informed consent kepada pasien dan atau keluarganya"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Operasi strabismus - Manajemen Refleks Okulokardiak', 'Anestesi Pediatrik', 17,
  'Seorang anak laki-laki berusia 6 tahun berat badan 20 kg akan direncanakan pembedahan koreksi strabismus. Pasien tidak memiliki riwayat kelainan jantung.', '1) Lakukan evaluasi pra anestesi!
2) Sebutkan problem aktual dan potensial!
3) Lakukan Tindakan intubasi untuk general anestesi pada pasien ini!
4) Pada saat operasi berlangsung 40 menit terjadi penurunan nadi, sebutkan diagnosis yang terjadi pada pasien ini dan manajemen nya.',
  'INSTRUKSI UMUM:
1. Pastikan identitas peserta ujian pada kartu ujian.
2. Tulislah nama dan nomor peserta ujian pada lembar penilaian.
3. Amatilah dan berilah skor (0/1/2/3) atas tugas yang dikerjakan peserta ujian serta skor Global Rating sesuai rubrik penilaian.
4. Hindarilah interupsi dan/atau tindakan selain daripada yang diminta dalam instruksi penguji.
5. Berikan informasi/hasil yang dibutuhkan secara lisan/tulisan hanya apabila peserta ujian telah melakukan dan/atau mengusulkan jenis pemeriksaan yang dimaksud (perhatikan instruksi khusus).
6. Taatilah peraturan serta etika penguji selama menjalankan tugas sebagai penguji OSCE!

INSTRUKSI KHUSUS:
(1) Penguji menilai peserta melakukan evaluasi pra anestesi. Informasi yang diberikan jika ditanya:
Anamnesis: AMPLE: Alergi: tidak ada, Medication: tidak ada, Past medical history: tidak ada, Last meal: 6 jam yang lalu, Event: strabismus.
Pemeriksaan fisik: Kesadaran Compos mentis, frekuensi nafas 18-20 x/menit, suara pernafasan vesikuler suara tambahan tidak ada, SaO2 99% dengan udara bebas. Tekanan darah 90/60 mmHg, Nadi 88 x/menit, kuat, Jantung: suara jantung normal, Suhu 37oC. Pemeriksaan lainnya dalam batas normal.
Pemeriksaan penunjang: Hasil Laboratorium: dalam batas normal.
(2) Penguji menilai peserta menyebutkan problem aktual dan potensial.
(3) Penguji menilai peserta melakukan tindakan anestesi pada pasien ini (Intubasi pada pediatrik).
(4) Penguji menilai peserta menyebutkan diagnosis dan manajemennya (Occulocardiac reflex dan tatalaksananya).', ARRAY['Peralatan kamar operasi', 'Manekin intubasi pediatrik', 'Laringoskop blade 2,3', 'ETT 5, 5,5 dan 6', 'Oropharyngeal tube no 1,2', 'Suction cath no 10', 'Sungkup muka no 1, 2', 'Jackson Rees breathing circuit', 'Spuit berlabel', 'Sulfast Atropin 0,25 mg', 'Midazolam 5 mg', 'Fentanyl / Remifentanyl / Morphine / Pethidin', 'Propofol', 'Relaxan'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Anamnesis: AMPLE (Alergi, Medication, Past medical history, Last meal, Event)", "Pemeriksaan fisik: Kesadaran, frekuensi nafas, suara pernafasan, SaO2, Tekanan darah, Nadi, Jantung, Suhu, Pemeriksaan lainnya dalam batas normal", "Pemeriksaan penunjang: Hasil Laboratorium dalam batas normal"]}, {"aspect": "Problem aktual dan potensial", "weight": 1, "items": ["Problem aktual: Pasien pediatri", "Problem potensial: Occulocardiac reflex", "Problem potensial: Cardiac arrest", "Problem potensial: Malignant hipertermia"]}, {"aspect": "Keterampilan Klinis (Intubasi pada pediatrik)", "weight": 4, "items": ["Memakai sarung tangan non steril", "Menyiapkan peralatan intubasi (STATICS): laringoskop dan stetoskop, ETT dengan 3 ukuran (ID 5, 5,5 dan 6), Oropharyngeal airway, plester, Introducer, Connector, Suction berfungsi baik", "Menyiapkan obat anestesi yang diperlukan", "Melakukan premedikasi", "Memberikan preoksigenasi dengan O2 100% selama 3 – 5 menit", "Menggunakan obat hipnotik – sedatif untuk induksi dengan agen intravena, pelumpuh otot kerja cepat (Rocuronium 0,6 – 1,2 mg/kgbb, tidak menggunakan Suksinilkolin)", "Melakukan intubasi setelah pelumpuh otot bekerja", "Menyambungkan connector ETT dengan sirkuit anestesi", "Melakukan konfirmasi posisi ETT", "Fiksasi plester"]}, {"aspect": "Monitoring dan manajemen penyulit", "weight": 2, "items": ["Diagnosis: Occulocardiac reflex", "Manajemen tatalaksana: Meminta operator untuk stop manipulasi mata", "Manajemen tatalaksana: Oksigenasi 100%", "Manajemen tatalaksana: Pastikan kedalaman anestesi", "Manajemen tatalaksana: Pemberian sulfas atropine 0,02 mg/kg"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan setiap tindakan dengan berhati-hati dan teliti sehingga tidak membahayakan pasien dan diri sendiri", "Memperhatikan kenyamanan pasien", "Melakukan tindakan sesuai prioritas", "Menunjukkan rasa hormat kepada pasien", "Mengetahui keterbatasan dengan merujuk atau melakukan konsultasi bila diperlukan"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Apendisitis akut', 'Anestesi Umum & Regional', 20,
  'Seorang Perempuan berusia 25 tahun dengan BB 60 Kg datang ke IGD RS dengan keluhan utama nyeri di perut kanan bawah sejak 3 hari yang lalu pasien juga mengeluhkan mual dan muntah satu hari ini. Pasien didiagnosis Appendicitis akut direncanakan operasi apendiktomi.', 'Lakukan evaluasi pra anestesia terhadap pasien tersebut.
Sebutkan problem aktual dan problem potensial terhadap pasien tersebut.
Sebutkan persiapan sebelum tindakan anestesi.
Lakukan tindakan spinal anestesi pada pasien tersebut.',
  'INSTRUKSI UMUM
Pastikan identitas peserta ujian pada kartu ujian
Tulislah nama dan nomor peserta ujian pada lembar penilaian!
Amatilah dan berilah skor (0/1/2/3) atas tugas yang dikerjakan peserta ujian serta skor Global Rating sesuai rubrik penilaian
Hindarilah interupsi dan/atau tindakan selain daripada yang diminta dalam instruksi penguji!
Berikan informasi/hasil yang dibutuhkan secara lisan/tulisan hanya apabila peserta ujian telah melakukan dan/atau mengusulkan jenis pemeriksaan yang dimaksud (perhatikan instruksi khusus)!
Taatilah peraturan serta etika penguji selama menjalankan tugas sebagai penguji OSCE - ATI!

INSTRUKSI KHUSUS
Penguji mengamati dan menilai tindakan pra anestesia yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta.

Peserta melakukan pemeriksaan fisik
Frekuensi napas 20 x/mnt, Suara pernapasan vesikuler, Suara tambahan tidak dijumpai.
Akral Hangat, merah, kering, tekanan darah 100/70 mmHg denyut nadi 90 x/I T/V cukup, turgor baik, temperature 38,5 C.
Kesadaran kompos mentis
VAS Diam 3 dan bergerak 6 (pada skala 1 - 10 cm).

Peserta menanyakan
Anamnese
Alergi (-), Medication (-), Past illness (-), Last meal 6 jam sebelum masuk rumah sakit, Event (-) nyeri pada perut kanan bawah
Riwayat penyakit dahulu: tidak pernah sakit yang serius.

Pemeriksaan penunjang
Hasil Laboratorium :
Darah Rutin : Hb 12 gr/dl, Ht 36% Leukosit 16000/mm3, trombosit 310.000/mm3
Faal Hemostasis : PT 10.9(12.2), APTT 35.8 (30.7), INR 1.5
Na 135 meq/L, Kalium 3.5 meql/L,Cl 110 mmol/L
Glukosa : 98 mg/dl.

Penguji menilai peserta menyebutkan problem aktual dan potensial pada pasien ini.
Problem aktual
Nyeri
Dehidrasi

Potensial problem :
Blok Spinal tinggi
Resusitasi cairan tidak adekuat
Nyeri paska operasi

Penguji menilai peserta menyebutkan persiapan sebelum tindakan anestesi.
Puasa atau nothing per oral
Rehidarasi dengan cairan kristaloid
Pemberian antipiretik
Menilai kecukupan cairan dengan penilaian vital sign atau dengan tilt test atau pasive leg rising
Pemberian analgetik
Pemberian antibiotik

Penguji menilai peserta melakukan keterampilan tindakan spinal anestesi.
Teknik Anestesi Spinal
Menyiapkan spinal set, memilih jenis jarum spinal yang sesuai, obat regional anestesi dan obat emergensi serta alat pelindung diri, menyiapkan obat anestesi umum yang diperlukan, mengecek mesin anestesi dan alat monitor pasien.
Posisi pasien : posisi duduk Left lateral decubitus, sebelumnya diberikan analgesia.
Membuat landmark dan menentukan titik puncture.
Cuci tangan steril, memakai baju steril dan handschoen.
Sterilisasi daerah puncture, tutup dengan duk lobang steril.
Infiltrasi lokal anestesi.
Puncture spinal anestesi sampai keluar LCS .
Barbotase dan memasukkan obat lokal Anestesi.
Memposisikan pasien kembali.
Menilai keberhasilan blok dengan pinprick dan bromage scale.

Penguji menilai komunikasi, edukasi serta perilaku profesionalisme peserta.', ARRAY['Peralatan ruang operasi', 'Manekin spinal', 'Jarum spinal 25', 'Jarum spinal 26', 'Jarum spinal 27', 'Nampan alat', 'Duk lobang', 'Cawan dengan label povidone iodine', 'Cawan dengan label alkohol', 'Korentang', 'Kassa', 'Topi', 'Masker', 'Sarung tangan steril 6,5', 'Sarung tangan steril 7', 'Sarung tangan steril 7,5', 'Alkohol 70%', 'Povidone iodine 10%', 'Spuit 5 cc', 'Spuit 10 cc', 'Plester', 'Gunting', 'Obat anestesi lokal (lidocaine)', 'Obat anestesi lokal (bupivacaine)', 'Obat anestesi lokal (ropivacaine)'], '[{"aspect": "Evaluasi Pra anestesi", "weight": 2, "items": ["Anamnese AMPLE", "Pemeriksaan fisik", "Pemeriksaan penunjang"]}, {"aspect": "Problem aktual dan Problem potensial", "weight": 2, "items": ["Nyeri", "Perdarahan", "Blok spinal tinggi", "Resusitasi cairan tidak adekuat", "Nyeri paska Anestesi."]}, {"aspect": "Rencana Tindakan anestesi", "weight": 2, "items": ["Puasa atau nothing per oral", "Rehidarasi dengan cairan kristaloid", "Pemberian antipiretik", "Menilai kecukupan cairan dengan penilaian vital sign atau dengan tilt test atau pasive leg rising", "Pemberian analgetik", "Pemberian antibiotik"]}, {"aspect": "Keterampilan klinis (Tindakan Spinal Anestesi)", "weight": 3, "items": ["Menyiapkan spinal set, memilih jenis jarum spinal yang sesuai, obat regional anestesi dan obat emergensi serta alat pelindung diri, menyiapkan obat anestesi umum yang diperlukan, mengecek mesin anestesi dan alat monitor pasien.", "Posisi pasien : posisi duduk Left lateral decubitus, sebelumnya diberikan analgesia.", "Membuat landmark dan menentukan titik puncture.", "Cuci tangan steril, memakai baju steril dan handschoen.", "Sterilisasi daerah puncture, tutup dengan duk lobang steril.", "Infiltrasi lokal anestesi.", "Puncture spinal anestesi sampai keluar LCS .", "Barbotase dan memasukkan obat lokal Anestesi.", "Memposisikan pasien kembali.", "Menilai keberhasilan blok dengan pinprick dan bromage scale."]}, {"aspect": "Komunikasi dan Perilaku profesional", "weight": 1, "items": ["Meminta izin secara lisan", "melakukan setiap tindakan dengan berhati-hati dan teliti sehingga tidak membahayakan pasien dan diri sendiri", "memperhatikan kenyamanan pasien", "melakukan tindakan sesuai prioritas", "menunjukkan rasa hormat kepada pasien", "mengetahui keterbatasan dengan merujuk atau melakukan konsultasi bila diperlukan"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Cushing Reflek – Ventilator dan Tatalaksana Peningkatan TIK', 'Resusitasi & Critical Care', 17,
  'Seorang laki laki berusia 45 tahun, panjang badan 163 cm dirawat di ICU setelah menjalani operasi craniotomi evakuasi SDH dua hari yang lalu, dengan GCS E4M5VEtt direncanakan untuk ekstubasi, namun tiba tiba pasien mengalami kejang', '1. Lakukan initial assesment pada kasus tersebut
2. Usulkan pada penguji pemeriksaan penunjang dan interpretasinya!
3. Sampaikan pada penguji tata laksana sesuai diagnosis tersebut
4. Lakukan tatalaksana setting ventilator, jika saat ini didapatkan EtCO2 50',
  'INSTRUKSI UMUM
1. Pastikan identitas peserta ujian pada kartu ujian
2. Tulislah nama dan nomor peserta ujian pada lembar penilaian!
3. Amatilah dan berilah skor (0/1/2/3) atas tugas yang dikerjakan peserta ujian serta skor Global Rating sesuai rubrik penilaian.
4. Hindarilah interupsi dan/atau tindakan selain daripada yang diminta dalam instruksi penguji!
5. Berikan informasi/ hasil yang dibutuhkan secara lisan/ tulisan hanya apabila peserta ujian telah melakukan dan/ atau mengusulkan jenis pemeriksaan yang dimaksud (perhatikan instruksi khusus)!
6. Taatilah peraturan serta etika penguji selama menjalankan tugas sebagai penguji OSCE - ATI!

INSTRUKSI KHUSUS
1. Penguji menilai kemampuan peserta untuk melakukan initial assesment. Penguji menyampaikan hasil setelah kandidat melakukan pemeriksaan.
Hasil pemeriksaan :
Airway : Bebas terintubasi
Breathing : Ventilator : Pressure control : PC 12 frekuensi 15 PEEP 5 FiO2 30% didapatkan tidal volume ekspirasi 300 ml frekuensi 10 x/menit minute volume ekspirasi 3,0 l ,SpO2 98% etCO2 50, rektrasi iga (-), , pernafasan cuping hidung (-) , suara nafas vesikuler (+/+)
Setting ventilator sesuai dengan yang tampak di ventilator :
Circulation : Tekanan darah 190/110 mmHg, Laju nadi 48 kali/menit teraba halus, akral dingin. Temperatur 36.5C
Disability : Pasien berespon dengan rangsangan nyeri, pupil anisokor (6/3) RC (+ lambat/+)
2. Penguji memberikan hasil pemeriksaan penunjang setelah diajukan peserta
AGD : pH : 7.199 pCO2 : 53.1 pO2 : 150 HCO3 :20.7 BE : -7 SaO2 98%
Interpretasi : Acidosis respiratorik dan metabolik,
Hb 7,4 Ht 25 Leukosit 10.000 Trombosit 230.000
Interpretasi : Anemia
CT scan : Intepretasi : Midline shift : Edema cerebri, didapatkan midline shift, ventrikel menyempit
3. Peserta ujian menyebutkan tata laksana sesuai diagnosis :
a. Posisi head up 30 derajad
b. Kontrol ventilasi : Hiperventilasi target PCO2 30-35.
c. Terapi hiperosmoler , mannitol 0,25 – 1 gr/kgBB
d. Ventrikulostomi
e. Kraniektomi
f. Koma barbiturate
g. Mild Hypotermi
h. Tranfusi PRC target Hb >10
4. Penguji menilai setting ventilasi mekanik peserta ujian
1. Menentukan mode ventilator: Pressure Control atau Volume Control
2. Menentukan Predicted Body Weight (PBW)
PBW= 50 + 0,91 x (160-152,4) = 59,6 ∾ 60 kg
3. Menentukan Volume Tidal (VT) = 6-8 ml/kg
VT = 360-480 ml (Jika, Pressure control maka P inspirasi disetting sampai target VT tersebut)
4. Menetukan Minute Ventilation (MV)
MV = 100 ml/kg = 5 L
5. Menentukan laju napas (RR)
RR = MV/VT = 11-14 x/menit
6. Menentukan PEEP
PEEP awal = 5 cmH2O
7. Menentukan FiO2
FiO2 awal 100%, kemudian diturunkan sampai SpO2 >95%
8. Menentukan I:E ratio
I:E ratio awal = 1:2
9. Mengamati Pplateau di monitor
Pplateau tidak lebih dari 30 cmH2O
10. Memeriksa AGD pasca setting awal', ARRAY['Setting Ruang ICU', 'Setting peralatan ICU', 'Manekin', 'Alat dan obat intubasi', 'Ventilator', 'Flashlight', 'Foto CT-scan', 'Kalkulator'], '[{"aspect": "Initial Assessment / Primary Survey", "weight": 2, "items": ["Pemeriksaan tanda vital", "Airway", "Breathing", "Circulation", "Disability"]}, {"aspect": "Kemampuan Tes / Prosedur Klinis atau Interpretasi Data untuk Menunjang Diagnosis", "weight": 2, "items": ["Mengusulkan pemeriksaan penunjang dan memberikan interpretasinya dengan tepat meliputi pemeriksaan: DL", "Mengusulkan pemeriksaan penunjang dan memberikan interpretasinya dengan tepat meliputi pemeriksaan: AGD", "Mengusulkan pemeriksaan penunjang dan memberikan interpretasinya dengan tepat meliputi pemeriksaan: CT - scan"]}, {"aspect": "Kemampuan Penatalaksanaan Pasien Kritis dan Penyulit (Farmakologis dan Non-Farmakologis)", "weight": 2, "items": ["Menyebutkan tata laksana sesuai dengan diagnosis: Posisi head up 30 derajad", "Menyebutkan tata laksana sesuai dengan diagnosis: Kontrol ventilasi : Hiperventilasi target PCO2 30-35.", "Menyebutkan tata laksana sesuai dengan diagnosis: Terapi hiperosmoler , mannitol 0,25 – 1 gr/kgBB", "Menyebutkan tata laksana sesuai dengan diagnosis: Ventrikulostomi", "Menyebutkan tata laksana sesuai dengan diagnosis: Kraniektomi", "Menyebutkan tata laksana sesuai dengan diagnosis: Koma barbiturate", "Menyebutkan tata laksana sesuai dengan diagnosis: Mild Hypotermi", "Menyebutkan tata laksana sesuai dengan diagnosis: Tranfusi PRC target Hb >10"]}, {"aspect": "Mampu melakukan penatalaksanaan pasien kritis dengan LENGKAP (Ventilator Setting)", "weight": 3, "items": ["Menentukan mode ventilator: Pressure Control atau Volume Control", "Menentukan Predicted Body Weight (PBW)", "Menentukan Volume Tidal (VT) = 6-8 ml/kg", "Menentukan Minute Ventilation (MV)", "Menentukan laju napas (RR)", "Menentukan PEEP", "Menentukan FiO2", "Menentukan I:E ratio", "Mengamati Pplateau di monitor", "Memeriksa AGD pasca setting ventilator"]}, {"aspect": "Komunikasi, Edukasi dan Profesionalisme", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan setiap tindakan dengan berhati-hati dan teliti sehingga tidak membahayakan pasien dan diri sendiri", "Memperhatikan kenyamanan pasien", "Melakukan tindakan sesuai prioritas", "Menunjukan rasa hormat kepada pasien", "Mengetahui keterbatasan dengan merujuk atau melakukan konsultasi bila diperlukan"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Laparoskopi Appendiktomi - Intubasi', 'Anestesi Umum & Regional', 17,
  'Seorang laki-laki usia 34 tahun, didiagnosis dengan appendisitis akut yang akan dilakukan operasi laparoskopi appendiktomi emergensi.', '1. Lakukan evaluasi pra anestesi!\n2. Sebutkan problem aktual – potensial pada kasus!\n3. Lakukan manajemen anestesi pada kasus tersebut berupa anestesi umum dengan intubasi!',
  'Penguji menilai evaluasi pra operasi (anamnesis AMPLE, pemeriksaan fisik tanda vital, sistem pernapasan LEMON & MOAN, sirkulasi, abdomen, pemeriksaan penunjang lab), diagnosa dan problem (aktual: infeksi, nyeri; potensial: hiperkapnia, gangguan ventilasi/hemodinamik karena insuflasi abdomen, refleks vagal, emfisema subkutan, PONV), tindakan anestesi umum intubasi (persiapan, monitoring EKG/TD/SpO2/EtCO2, supine, preoksigenasi, induksi, intubasi ETT 7.5, rumatan, cairan, ekstubasi), komunikasi & perilaku profesional.', ARRAY['Meja peralatan', 'Meja operasi', 'Manekin intubasi', 'Stetoskop', 'Monitor Pasien', 'Monitor End Tidal CO2', 'Stylet', 'Laringoskop blade 3, 4', 'Suction no 12, 14', 'Sungkup Muka no 3, 4', 'ETT 7,5 7 6.5', 'Plester', 'Mesin anestesi dengan ventilator', 'Midazolam', 'Fentanyl', 'Propofol', 'Atracurium', 'Rocuronium', 'Prostigmin', 'Naloxone', 'Sulfas Atropine', 'Adrenalin', 'Sarung tangan non steril'], '[{"aspect": "Evaluasi Pra Operasi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik lengkap termasuk tanda vital, sistem pernapasan (LEMON & MOAN), sirkulasi, dan abdomen", "Melakukan pemeriksaan penunjang (laboratorium)"]}, {"aspect": "Diagnosa dan Problem Aktual - Potensial", "weight": 2, "items": ["Menyebutkan problem aktual: Infeksi dan Nyeri", "Menyebutkan problem potensial: Hiperkapnia, Gangguan ventilasi dan hemodinamik karena posisi Trendelenburg dan insuflasi abdomen, Refleks vagal, Emfisema subkutan, PONV"]}, {"aspect": "Tindakan Anestesi Umum dengan Intubasi", "weight": 3, "items": ["Persiapan alat, obat anestesi dan emergensi", "Monitoring fungsi vital (EKG, TD, SpO2, EtCO2)", "Pasien diposisikan supine dan dilakukan preoksigenasi O2 100%", "Pemberian opioid, induksi intravena, dan pelumpuh otot", "Intubasi dengan ETT No 7.5", "Rumatan anestesi dengan inhalasi, opioid, dan pelumpuh otot intermiten", "Monitoring EtCO2, EKG, TD, SpO2 intraoperasi", "Manajemen cairan intraoperasi", "Menghentikan obat inhalasi dan melakukan ekstubasi setelah nafas spontan adekuat"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan kepada pasien sebelum tindakan", "Melakukan setiap tindakan dengan berhati-hati dan teliti sehingga tidak membahayakan pasien", "Memperhatikan kenyamanan pasien dan menunjukkan rasa hormat", "Melakukan tindakan sesuai prioritas", "Mengetahui keterbatasan dengan merujuk atau melakukan konsultasi"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Anestesi Spinal pada Fraktur Kruris', 'Anestesi Umum & Regional', 20,
  'Seorang laki-laki umur 25 tahun dengan BB 60 Kg mengalami kecelakaan lalu lintas. Masuk Ke IGD dengan fraktur tertutup kruris Sinistra, akan dilakukan tindakan ORIF. Tidak terdapat cedera kepala. Riwayat kesehatan sebelumnya baik.', 'Lakukan preoperatif visit terhadap pasien tersebut!\nSebutkan problem aktual dan problem potensial terhadap pasien tersebut!\nLakukan tindakan spinal anestesi pada pasien tersebut!',
  'Penguji menilai: evaluasi praoperasi (Primary survey, anamnesa AMPLE, pemeriksaan fisik, lab), problem (aktual: nyeri, perdarahan; potensial: blok spinal tinggi, nyeri pasca anestesi, intoksikasi lokal anestesi), tindakan anestesi spinal (persiapan spinal set/obat, ganjal bantal, posisi duduk/lateral decubitus, landmark, asepsis, infiltrasi, puncture keluar LCS, obat masuk, monitoring blok pinprick/bromage scale), penanganan intoksikasi lokal anestesi (LA toxicity: stop injeksi, oksigenasi 100%, airway control/intubasi, benzodiazepines/propofol untuk kejang, intralipid 20% bolus 1.5 mL/kg, infus 0.25 mL/kg/min), komunikasi & perilaku profesional.', ARRAY['Meja dan kursi dokter', 'Kursi pasien', 'Meja dan kursi penguji', 'Meja peralatan', 'Meja operasi', 'Spinal set', 'Jarum Spinal no. 25, 26, 27', 'Obat lokal anestesi (lidocaine, bupivacaine)', 'Spuit 3 ml, 5 ml', 'Stetoskop', 'Monitor Pasien', 'Sungkup Muka', 'Sarung tangan non-steril', 'Tempat sampah', 'Tissue', 'Jam dinding', 'VAS skor', 'Pen light', 'Manekin Spinal'], '[{"aspect": "Evaluasi Praoperasi", "weight": 2, "items": ["Melakukan Primary survey (Airway, Breathing, Circulation, Disability, Exposure)", "Melakukan anamnesa AMPLE lengkap", "Melakukan pemeriksaan fisik klinis lengkap", "Melakukan pemeriksaan penunjang (laboratorium)"]}, {"aspect": "Problem aktual dan Problem potensial", "weight": 2, "items": ["Menyebutkan problem aktual: Nyeri, Perdarahan", "Menyebutkan problem potensial: Blok spinal tinggi, Nyeri pasca anestesi, Intoksikasi lokal anestesi"]}, {"aspect": "Keterampilan klinis (Tindakan Spinal Anestesi)", "weight": 2, "items": ["Menyiapkan spinal set, memilih jenis jarum spinal, obat regional dan emergensi serta APD", "Mengecek mesin anestesi dan monitor", "Mengatur posisi pasien (duduk / Left lateral decubitus) dengan analgesia", "Menentukan landmark dan titik puncture", "Cuci tangan steril, memakai baju steril, dan handschoen steril", "Desinfeksi daerah puncture dan pasang duk lobang steril", "Infiltrasi lokal anestesi pada area puncture", "Melakukan puncture spinal anestesi sampai keluar LCS", "Melakukan barbotase dan memasukkan obat lokal anestesi", "Memposisikan pasien kembali dan menilai keberhasilan blok dengan pinprick dan bromage scale", "Menjelaskan tatalaksana komplikasi intoksikasi lokal anestesi (LA toxicity) termasuk pemberian intralipid 20%"]}, {"aspect": "Komunikasi dan Perilaku profesional", "weight": 3, "items": ["Memperkenalkan diri kepada keluarga pasien dengan menyebutkan nama dan keahlian", "Memberikan informasi kepada pasien & keluarga secara ramah dan rasa hormat", "Menjelaskan rencana tindakan spinal anestesi, problem yang mungkin timbul saat atau pasca operasi, serta efek samping/risiko secara lengkap", "Melakukan tindakan dengan memperhatikan kenyamanan pasien", "Melakukan setiap tindakan dengan berhati-hati dan teliti"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Gagal Napas dan Syok Kardiogenik - Ventilator Setting', 'Resusitasi & Critical Care', 17,
  'Seorang laki-laki berusia 65 tahun, tinggi badan 65 inchi (165 cm), datang dengan keluhan sesak nafas. Pada pemeriksaan fisik didapatkan RR 38 x/menit, retraksi iga (+), sianosis, pernapasan cuping hidung, ronkhi basah (+) seluruh lapangan paru, SpO2 82% (NRM 12 L/m). Perfusi dingin/basah/pucat, HR 130 x/menit teraba halus, TD 70/40 mmHg, JVP meningkat. Kesadaran somnolen. Pasien dibawa ke ICU dan dilakukan intubasi.', '1. Usulkan pada penguji pemeriksaan penunjang dan interpretasinya!\n2. Tentukan diagnosis klinis pasien ini!\n3. Lakukan tatalaksana setting ventilator dan sampaikan penatalaksanaan farmakologis pasien ini!',
  'Penguji menilai: interpretasi data (AGD: asidosis mixed metabolik & respiratorik dengan hipoksemia, rontgen: kardiomegali & edema paru, darah: anemia & leukositosis, laktat: 5 mmol/L, EKG: OMI inferior), diagnosis klinis (gagal napas tipe 1 & 2, syok kardiogenik, edema paru akut), setting ventilator (PBW = 57 kg, mode PC/VC, Volume Tidal = 342 - 456 ml, PPlat <= 30, PEEP = 8-10, FiO2 <= 0.6 target SpO2 88-95%, RR = 12-16, I:E = 1:2), tatalaksana farmakologis (restriksi cairan, inotropik, diuretik, sedasi/analgesia, stress ulcer prevention), komunikasi & perilaku profesional.', ARRAY['Setting Ruang ICU', 'Setting peralatan ICU', 'Ventilator', 'Manekin airway trainer dengan ETT', 'Light box', 'Foto toraks kardiomegali dan edema paru', 'EKG OMI inferior'], '[{"aspect": "Interpretasi Data Penunjang", "weight": 3, "items": ["Mengusulkan pemeriksaan AGD dan memberikan interpretasi asidosis metabolik & respiratorik dengan hipoksemia", "Mengusulkan foto thoraks dan memberikan interpretasi kardiomegali dan edema paru", "Mengusulkan pemeriksaan EKG dan memberikan interpretasi OMI inferior", "Mengusulkan pemeriksaan darah rutin (anemia, leukositosis) dan laktat (hiperlaktanemia)"]}, {"aspect": "Diagnosis Definitif Pasien Kritis", "weight": 2, "items": ["Menyebutkan diagnosis: Gagal Napas Tipe 1 dan 2", "Menyebutkan diagnosis: Syok Kardiogenik", "Menyebutkan diagnosis: Edema Paru Akut"]}, {"aspect": "Tatalaksana Setting Ventilator (Non-Farmakologis)", "weight": 4, "items": ["Menghitung Predicted Body Weight (PBW) dengan benar (57 kg)", "Menentukan mode ventilator (Pressure / Volume Control) dan Volume Tidal awal (6-8 ml/kg PBW = 342-456 ml)", "Menetapkan target PPlat <= 30 cmH2O and PEEP awal 8-10 cmH2O", "Menentukan FiO2 <= 0.6 dengan target SpO2 88%-95% atau PaO2 55-80 mmHg", "Menentukan laju napas (RR) 12-16 x/menit dan I:E ratio 1:2"]}, {"aspect": "Tatalaksana Farmakologis Pasien Kritis", "weight": 2, "items": ["Menjelaskan restriksi terapi cairan dan pemberian diuretik", "Menjelaskan pemberian inotropik", "Menjelaskan pemberian sedasi dan analgesia serta pencegahan stress ulcer"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan sebelum melakukan tindakan", "Melakukan setiap tindakan dengan berhati-hati dan teliti sehingga tidak membahayakan pasien", "Memperhatikan kenyamanan pasien dan menunjukkan rasa hormat"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Painless Labour – Anestesi Epidural', 'Anestesi Obstetrik', 17,
  'Seorang perempuan usia 20 tahun direncanakan partus spontan pervaginam dengan Epidural Labour Anesthesia. Pasien dengan keluhan mules – mules ingin melahirkan, riwayat keluar lendir bercampur darah dari kemaluan (+) hal ini dialami sejak 6 jam sebelum masuk rumah sakit. Ini merupakan hamil pertama. Mual (+), riw. Hipertensi selama hamil ( - ).', '1. Lakukan evaluasi pra anestesia pada pasien ini!\n2. Sebutkan problem aktual – potensial yang mungkin terjadi pada pasien ini!\n3. Lakukan anestesi epidural pada pasien ini!\n4. Pada bukaan serviks lengkap, pasien mengeluhkan nyeri. Jelaskan tindakan saudara!',
  'Penguji menilai: evaluasi praoperasi (anamnesis AMPLE, fisik: BB 98 kg, TB 160 cm, TD 130/90, HR 114, RR 22, NRS 3-4, DJJ 140, LEMON score baik, cervix 3cm, lab: Hb 9, WBC 14.500, Plt 155.000), problem (aktual: hamil, cemas, nyeri, obesitas; potensial: alergi obat, mual muntah, hipotensi), tindakan epidural (alat/obat, monitor vital, posisi decubitus/duduk, landmark L3-L4 Tuffier''s line, steril, infiltrasi, jarum Tuohy, LOR/Hanging Drop, kateter 3-5cm, test dose: 3ml lidokain 2% + epinefrin 1:200.000, obat masuk, cek blok), tatalaksana penyulit bukaan lengkap (posisi head-up, tambahan volume anestesi lokal).', ARRAY['Peralatan ruang operasi', 'Manekin spinal/epidural', 'Epidural set', 'Nampan alat', 'Duk lobang', 'Cawan', 'Povidone iodine 10%', 'Alkohol 70%', 'Korentang', 'Kassa', 'Topi dan Masker', 'Sarung tangan steril', 'Spuit 5 cc, 10 cc', 'Plester', 'Gunting', 'Obat anestesi lokal (lidocaine, bupivacaine, ropivacaine)'], '[{"aspect": "Evaluasi Pra Anestesia", "weight": 2, "items": ["Melakukan anamnesa langsung kepada pasien (AMPLE lengkap)", "Melakukan pemeriksaan fisik obstetri dan klinis lengkap", "Melakukan pemeriksaan penunjang (laboratorium)"]}, {"aspect": "Diagnosa dan Problem Aktual - Potensial", "weight": 2, "items": ["Menyebutkan problem aktual: Hamil, Cemas, Nyeri, Obesitas", "Menyebutkan problem potensial: Alergi obat (asam mefenamat), Mual muntah, Hipotensi"]}, {"aspect": "Keterampilan Klinis (Tindakan Anestesi Epidural)", "weight": 3, "items": ["Persiapan alat, obat epidural dan emergensi", "Pemasangan monitor standar dan memantau tanda vital", "Mengatur posisi pasien (duduk / lateral decubitus kiri)", "Menentukan landmark L3-L4 (Tuffier''s line) dan melakukan desinfeksi serta pasang duk steril", "Memakai APD steril (gaun, sarung tangan steril) dan cuci tangan steril", "Infiltrasi lokal anestesi", "Melakukan penusukan jarum Tuohy dan identifikasi ruang epidural dengan teknik LOR / Hanging Drop", "Insersi kateter epidural (3-5 cm di ruang epidural), pasang filter, dan fiksasi", "Memberikan test dose (3 ml lidokain 2% dengan epinefrin 1:200.000) dan memastikan respon negatif", "Memasukkan dosis terapeutik lokal anestesi secara bertahap dan menilai blok epidural"]}, {"aspect": "Monitoring dan Manajemen Penyulit", "weight": 2, "items": ["Memposisikan pasien head-up / setengah duduk apabila pasien mengeluhkan nyeri pada bukaan lengkap", "Memberikan tambahan volume anestesi lokal secara bertahap melalui kateter epidural"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan sebelum tindakan", "Melakukan setiap tindakan dengan berhati-hati dan teliti sehingga tidak membahayakan pasien", "Memperhatikan kenyamanan pasien and menunjukkan rasa hormat"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Anestesia Bedah Toraks - One Lung Ventilation (OLV)', 'Anestesi Umum & Regional', 17,
  'Seorang wanita 50 tahun datang dengan keluhan batuk darah sejak 10 tahun lalu. Pasien dengan BB 70 kg and TB 165 cm. Batuk darah dirasakan semakin memberat. Pasien telah menjalani terapi OAT selama 9 bulan di puskesmas namun keluhan tidak berkurang. Pasien tidak pernah mengeluh sesak. Pasien didiagnosis aspergilosis pulmo sinistra dan diprogram untuk operasi thoracotomi dekortikasi.', '1. Lakukan evaluasi pre anestesi (anamnesis, pemeriksaan fisik, dan pemeriksaan penunjang)!\n2. Tegakkan diagnosis pasien dan rencana anestesi pada pasien!\n3. Sebutkan problem pasien dan potensial problem pada pasien!\n4. Lakukan intubasi dengan pipa endotrakheal double lumen (DLT)!\n5. Bagaimana manajemen hipoksia saat one lung ventilation (OLV)?',
  'Penguji menilai: evaluasi praoperasi (anamnesis AMPLE, fisik B1-B6, lab, AGD: normal, spirometri: restriktif ringan, Ro: aspergilosis lobus inferior sinistra), diagnosis (aspergilosis pulmo sinistra pro thoracotomi dekortikasi, ASA 2), problem (restriktif ringan, obstruksi napas bawah, desaturasi), rencana anestesi (puasa, NGT/suction, rehidrasi, kateter urin, GAET dengan DLT Kiri 35), keterampilan intubasi DLT (alat/obat, monitor invasive line, preoksigenasi, induksi, rumus kedalaman Brodsky/Bahk, intubasi DLT Kiri 35, protokol konfirmasi DLT: cuff trakea/bronkus, klem lumen trakea, auskultasi napas unilateral kiri, atur VT OLV 4-6 cc/kg, rumatan, reversal), manajemen hipoksia OLV (cek DLT, FiO2 1.0, recruitment maneuver, PEEP, CPAP/oksigen paru non-dependen, ventilasi 2 paru jika berat, TIVA jika gagal).', ARRAY['Peralatan kamar operasi', 'Manekin intubasi dewasa', 'Laringoskop blade 3, 4', 'ETT DLT Kiri 35, 37', 'Spuit berlabel', 'Sulfas Atropin', 'Midazolam', 'Fentanyl/Sufentanil/Morphine', 'Propofol', 'Pelumpuh otot', 'Suction kateter no 10, 12', 'Oropharyngeal airway no 4, 5', 'Sungkup muka no 3, 4', 'Jackson Rees breathing circuit', 'Ambu bag'], '[{"aspect": "Evaluasi Pra Anestesia", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik lengkap B1-B6", "Melakukan pemeriksaan penunjang (Laboratorium, AGD, Ro Thorax, EKG, Spirometri)"]}, {"aspect": "Diagnosis dan Problem Aktual - Potensial", "weight": 2, "items": ["Menyebutkan diagnosis: Aspergilosis pulmo sinistra pro thoracotomi dekortikasi / lobektomi inferior sinistra, ASA 2", "Menyebutkan problem: Restriktif ringan, Obstruksi saluran napas bawah, resiko Desaturasi"]}, {"aspect": "Rencana Tindakan Anestesi", "weight": 2, "items": ["Menjelaskan rencana puasa dan pemasangan NGT serta kateter urin", "Menjelaskan rencana rehidrasi cairan kristaloid", "Menjelaskan rencana anestesi umum napas kendali dengan pipa endotrakheal double lumen (DLT)"]}, {"aspect": "Keterampilan Klinis (Intubasi dan Penempatan DLT)", "weight": 3, "items": ["Persiapan alat, obat anestesi & emergensi, serta monitoring (EKG, TD invasif A-line, CVC, SpO2, EtCO2)", "Melakukan preoksigenasi, induksi, dan pemberian pelumpuh otot", "Menghitung kedalaman insersi DLT berdasarkan tinggi badan pasien", "Melakukan intubasi dengan DLT Kiri ukuran 35/37", "Melakukan protokol konfirmasi posisi DLT dengan benar (inflasi cuff trakeal & bronkial, klem lumen trakeal, auskultasi suara napas unilateral)", "Mengatur parameter ventilator saat ventilasi satu paru (VT 4-6 cc/kgBB, rumatan inhalasi tanpa N2O, restriksi cairan)", "Menjelaskan prosedur pengakhiran anestesi (reversal pelumpuh otot, ekstubasi/penggantian DLT dengan ETT single lumen)"]}, {"aspect": "Manajemen Hipoksia saat One Lung Ventilation", "weight": 2, "items": ["Melakukan konfirmasi ulang posisi DLT", "Meningkatkan FiO2 menjadi 1.0", "Melakukan recruitment maneuver dan memberikan PEEP pada paru dependen", "Memberikan CPAP atau hembusan oksigen pada paru non-dependen (paru yang dioperasi)", "Melakukan ventilasi dua paru jika terjadi hipoksemia berat", "Menghentikan agen inhalasi yang menghambat HPV dan beralih ke TIVA jika diperlukan"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan sebelum tindakan", "Melakukan setiap tindakan dengan berhati-hati dan teliti sehingga tidak membahayakan pasien", "Memperhatikan kenyamanan pasien and menunjukkan rasa hormat"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Volvulus pada Anak - Rapid Sequence Induction', 'Anestesi Pediatrik', 17,
  'Anak laki-laki umur 3 bulan Berat Badan 5 kg didiagnosis Volvulus akan dilakukan operasi darurat.', '1. Lakukan evaluasi pra anestesi pada pasien tersebut!\n2. Sebutkan problem aktual dan potensial pada pasien ini!\n3. Sebutkan persiapan anestesi pada pasien ini!\n4. Lakukan tindakan intubasi pada pasien ini!',
  'Penguji menilai: evaluasi praoperasi (anamnesis AMPLE: muntah ASI 1 hari, lemas tidak mau menetek; vital sign: RR 40, HR 160, TD 60/40, T 38C; fisik: akral dingin, CRT >2s, mata cekung, bibir kering, turgor turun, somnolen, oliguria; lab: Na 130, K 3.0, Cl 90), problem (aktual: dehidrasi, pediatrik; potensial: aspirasi, laringospasme, desaturasi, bradikardia), persiapan anestesi (puasa, NGT/suction aktif, rehidrasi kristaloid 20ml/kg 30-60 menit, kateter urin, GA sleep apnea/RSI), keterampilan intubasi RSI (sarung tangan, STATICS ETT 4/4.5/5, obat, head up 30, preoksigenasi, induksi IV/Rocuronium 1.2mg/kg, HINDARI bagging/ventilasi tekanan positif, intubasi, konfirmasi, fiksasi).', ARRAY['Manequin intubasi infant', 'Laringoskop blade 1', 'ETT 2.5, 3.0, 3.5, 4.0, 4.5, 5.0', 'Spuit berlabel', 'Sulfas Atropin', 'Midazolam', 'Fentanyl/Remifentanil/Morphine', 'Propofol', 'Pelumpuh otot (Rocuronium)', 'Suction kateter no 10, 12', 'Oropharyngeal airway no 1, 2', 'Sungkup muka no 1, 2', 'Jackson Rees breathing circuit', 'Ambu bag'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik tanda-tanda dehidrasi dan vital sign secara sistematis", "Melakukan pemeriksaan penunjang (Laboratorium dan serum elektrolit)"]}, {"aspect": "Diagnosa dan Problem Aktual - Potensial", "weight": 2, "items": ["Menyebutkan problem aktual: Dehidrasi dan Pasien pediatrik", "Menyebutkan problem potensial: Aspirasi, Laringospasme, Desaturasi, Bradikardia"]}, {"aspect": "Rencana Tindakan Anestesi", "weight": 2, "items": ["Menjelaskan rencana puasa dan pemasangan NGT dengan suction aktif", "Menjelaskan rencana rehidrasi cairan cepat kristaloid 20 ml/kg dan pemantauan kateter urin", "Menjelaskan rencana general anestesi dengan teknik Rapid Sequence Induction (RSI)"]}, {"aspect": "Keterampilan Klinis (Intubasi RSI Pediatrik)", "weight": 3, "items": ["Persiapan alat STATICS (ETT ID 4, 4.5, 5), obat anestesi, dan APD", "Memposisikan pasien head-up minimal 30 derajat dan melakukan preoksigenasi O2 100% selama 3-5 menit", "Melakukan induksi intravena dan pemberian pelumpuh otot kerja cepat Rocuronium 1.2 mg/kg", "Menghindari pemberian ventilasi tekanan positif (bagging) sebelum intubasi untuk mencegah aspirasi", "Melakukan intubasi setelah pelumpuh otot bekerja, mengonfirmasi posisi ETT, dan melakukan fiksasi"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan kepada ibu pasien dan menunjukkan rasa empati/sopan santun", "Melakukan setiap tindakan dengan berhati-hati dan teliti sehingga tidak membahayakan pasien", "Memperhatikan kenyamanan pasien and menunjukkan rasa hormat"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Anestesi pada Operasi Mata – Pemasangan LMA', 'Anestesi Rawat Jalan & NORA', 17,
  'Seorang laki-laki usia 76 tahun berat badan 65 kg, tinggi badan 165cm, direncanakan untuk bedah rawat jalan untuk tindakan pemasangan Intraocular Lense (IOL). Pasien tidak memiliki riwayat refluks, riwayat hipertensi terkontrol. Pasien akan dilakukan anestesi umum atas permintaan pasien.', '1. Sebutkan problem aktual potensial!\n2. Lakukan induksi anestesia umum dan pemasangan Laryngeal Mask Airway (LMA)!\n3. Sebutkan kriteria pemulangan pasien bedah rawat jalan berdasarkan Post-anesthesia Discharge Scoring System (PADSS)!\n4. Sebutkan edukasi paska anestesi pasien ini!',
  'Penguji menilai: problem (aktual: hipertensi, geriatri; potensial: hemodinamik tidak stabil, tekanan intraokuler meningkat, refleks okulokardiak, efek sistemik obat mata), keterampilan LMA (alat/obat, backup ETT, monitor, LMA no 4, cek bocor, lubrikasi posterior, premedikasi, induksi/kedalaman, sniffing position, insersi LMA, inflasi, leak test, fiksasi), kriteria pulang (tabel PADSS: vital sign, aktivitas, mual, nyeri, perdarahan; skor >= 9 boleh pulang), edukasi pulang (pendamping dewasa, tidak boleh menyetir/mesin 24 jam, instruksi tertulis & kontak emergensi).', ARRAY['Mesin anestesi dan sirkuit anestesi', 'Stetoskop', 'LMA No. 3, 4', 'Oropharyngeal Airway 3, 4, 5', 'Plester', 'Gunting', 'Mesin suction', 'Kateter suction No. 10, 12', 'Sungkup No. 3, 4', 'Sarung tangan non-steril', 'Bantal intubasi', 'Spuit berlabel obat anestesi (propofol/midazolam/tiopental/fentanil/atrakurium/rokuronium/lidokain)', 'Spuit berlabel obat emergensi (sulfas atropin/adrenalin)', 'Spuit 20 cc', 'Ambu bag', 'Laringoskop blade 3, 4', 'ETT No. 7/7,5/8', 'Manikin intubasi dewasa'], '[{"aspect": "Diagnosa dan Problem Aktual - Potensial", "weight": 2, "items": ["Menyebutkan problem aktual: Hipertensi, Geriatri", "Menyebutkan problem potensial: Hemodinamik tidak stabil, Peningkatan tekanan intraokuler, Refleks okulokardiak, Penggunaan obat-obatan mata dengan efek sistemik"]}, {"aspect": "Keterampilan Klinis (Pemasangan LMA)", "weight": 4, "items": ["Persiapan alat LMA, backup ETT, obat induksi, dan monitoring tanda vital", "Memilih LMA no 4, memeriksa kebocoran cuff, dan memberikan lubrikasi di sisi posterior", "Melakukan premedikasi dan induksi anestesi hingga kedalaman yang adekuat", "Memposisikan pasien sniffing position dan melakukan insersi LMA secara smooth hingga hipofaring", "Inflasi cuff LMA, melakukan leak test, memantau obstruksi, dan melakukan fiksasi"]}, {"aspect": "Manajemen Pasca Anestesia (Kriteria PADSS)", "weight": 3, "items": ["Menjelaskan kriteria pemulangan pasien bedah rawat jalan menggunakan tabel Post-anesthesia Discharge Scoring System (PADSS)", "Menyebutkan bahwa pasien dinyatakan boleh dipulangkan jika total skor PADSS >= 9 dari total 10"]}, {"aspect": "Komunikasi, Edukasi, dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan sebelum tindakan", "Melakukan setiap tindakan dengan berhati-hati dan teliti sehingga tidak membahayakan pasien", "Menjelaskan edukasi pasca anestesi: didampingi orang dewasa, dilarang menyetir/mengoperasikan mesin dalam 24 jam, dan memberikan instruksi tertulis/kontak emergensi"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Laparoskopi Appendiktomi', 'Anestesi Umum & Regional', 17,
  'Seorang laki-laki 34 tahun datang dengan keluhan nyeri perut kanan bawah sejak 2 hari lalu. Pasien juga mengeluhkan demam, mual serta nafsu makan menurun. Pasien minum paracetamol 500 mg di rumah dan merasa demam berkurang. Pasien memeriksakan diri ke dokter spesialis bedah dan didiagnosa dengan Appendisitis akut yang akan dilakukan operasi laparoskopi appendiktomi. Pasien memiliki berat badan 110 kg, tinggi badan 170 cm.', 'Lakukan tindakan sesuai instruksi penguji.',
  'Penguji menilai kemampuan peserta untuk evaluasi pra operasi Anamnesis : A : riwayat alergi / asthma (-) M: Pasien meng konsumsi paracetamol 3x500mg P : pasien tidak pernah menderita penyakit kongenital ataupun kronis, riwayat tidur mengorok (+) L : 6 jam yang lalu E : nyeri perut kanan bawah sejak 2 hari lalu. Pasien juga mengeluhkan demam, mual serta nafsu makan menurun Pemeriksaan fisik B1 : Jalan nafas bebas, malampati 2, gigi ompong (-). RR 16 x/menit, napas spontan adekuat, retraksi (-). Suara nafas vesikuler Rh -/- Wheezing -/- SpO2 96% (oksigen 21%) B2 : nadi teraba kuat frekuensi 92 x/menit, tekanan darah 130/90 mmHg, mukosa mulut basah, turgor normal B3 : pasien tampak tenang B4 : Normal B5 : abdomen supel, bising usus normal, Nyeri tekan Mc Burney (+), Rovsing sign (+) B6 : Normal, suhu 37.5 C Penguji menilai Diagnosis dan Problem Aktual – Potensial ditegakkan peserta ujian Diagnosa : Laki-laki 34 tahun dengan appendisitis akut pro appendiktomi laparoskopi Problem aktual dan potensial: Obesitas Infeksi Nyeri Hiperkapnea Gangguan ventilasi dan hemodinamik karena posisi Trendelenburg Penguji menilai rencana tindakan anestesi yang diusulkan / dikerjakan peserta ujian Anestesi umum napas kendali dengan intubasi Penguji menilai pelaksanaan keterampilan klinis yang diusulkan / dikerjakan peserta ujian Persiapan alat, obat anestesi dan emergensi Monitoring fungsi vital yang meliputi EKG, Tekanan darah, SpO2, End tidal CO2 Preoksigenasi Induksi insuflasi menggunakan sevoflurane atau induksi iv menggunakan obat sedasi dan obat pelumpuh otot Intubasi dengan ETT no 7.5 Rumatan anestesi dengan obat agent inhalasi, narkotik fentanyl 1-2 mcg/kgBB, dan obat pelumpuh otot atracurium atau vecuronium atau rocuronium. Rumatan cairan dengan kristaloid Diberikan reversal neostigmin dan atropin Anestesi diakhiri, agent inhalasi dihentikan, dan ekstubasi dilakukan setelah pasien bernafas spontan dan adekuat Penguji menilai penatalaksanaanmonitoring / manajemen penyulit yang diusulkan / dikerjakan peserta ujian Menginformasikan kepada operator untuk menghentikan operasi sementara karena terjadi asidosis respiratorik Meningkatkan minute volume dengan cara hiperventilasi atau menaikkan volume tidal, pemberian PEEP dan modifikasi I : E rasio untuk menurunkan kadar CO2 (melihat monitor End Tidal CO2) Mempersilakan operator untuk melanjutkan operasi bila nilai End Tidal CO2 telah normal Penguji menilai Komunikasi, edukasi dan profesionalisme peserta ujian.', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Pneumothorax Ec Laparoscopy', 'Anestesi Umum & Regional', 17,
  'Seorang wanita 33 tahun datang dengan keluhan benjolan di perut sejak 2 tahun yang lalu. Benjolan dirasakan makin membesar dan nyeri terutama saat haid. Riwayat kehamilan (-) dengan riwayat Haid tidak teratur. Pasien memeriksakan diri ke dokter spesialis OBGYN dan didiagnosa dengan kista coklat ovarium yang akan dilakukan operasi kistektomi laparoscopy.', 'Lakukan evaluasi pre anestesi (anamnesis, pemeriksaan fisik, dan pemeriksaan penunjang).\nTegakkan diagnosis pasien dan rencana anestesi pada pasien.\nSebutkan problem pasien dan potensial problem pada pasien\nLima menit setelah operator melakukan insersi trocar dan insuflasi CO2, tekanan darah pasien turun secara tiba-tiba menjadi 70/35 mmHg, nadi 116x/menit, SpO2 82%, dan ETCO2 46 mmHg. Alarm mesin anestesi menyala dan terbaca sebagai peningkatan airway pressure. Dari pemeriksaan ETT clear tanpa obstruksi. Suara dasar vesikuler paru kanan hilang dan perkusi hemithoraks kanan didapatkan hipersonor \nSebutkan komplikasi yang terjadi pada pasien beserta tatalaksananya\nBagaimana manajemen paska operasi pada pasien',
  'Peserta ujian melakukan evaluasi praoperasi secara lengkap dan runut yang meliputi : Anamnesa AMPLE Anamnesis : A : riwayat alergi / asthma (-) M: Pasien tidak mengkonsumsi obat P : pasien tidak pernah menderita penyakit kongenital ataupun kronis L : 6 jam yang lalu E : benjolan di perut sejak 2 tahun yang lalu. Benjolan dirasakan makin membesar dan nyeri terutama saat haid. Pemeriksaan fisik B1 – B6 B1 : Jalan nafas bebas, malampati 1, gigi ompong (-). RR 12 x/menit, napas spontan adekuat, retraksi (-). Suara nafas vesikuler Rh -/- Wheezing -/- SpO2 100% (oksigen 21%) B2 : nadi teraba kuat frekuensi 72 x/menit , tekanan darah 120/70 mmHg, mukosa mulut basah, turgor normal B3 : pasien tampak tenang B4 : produksi urin 30 cc / jam B5 : abdomen supel, bising usus normal, teraba massa suprapubik B6 : suhu 36.6 C Diagnosa Wanita 33 tahun dengan kista coklat ovarium pro kistektomi laparoscopy status fisik ASA 1 plan GAET Potensial problem Hiperkarbia Pneumothorax Emfisema subkutan Penunjang untuk screening problem Laboratorium: Hemoglobin, hematokrit, Analisa gas darah EKG Sedia darah jika diperlukan Peserta ujian melakukan semua tahapan pemberian anestesi dengan benar dan runut meliputi : Persiapan alat dan obat anestesi dan emergensi Monitoring fungsi vital yang meliputi ECG, Tekanan darah, SpO2, End tidal CO2 Preoksigenasi Induksi insuflasi menggunakan sevoflurane atau induksi iv menggunakan obat sedasi dan obat pelumpuh otot Intubasi dengan ETT no 7.5 Rumatan anestesi dengan obat agent inhalasi , narkotik fentanyl 1-2 mcg/kgBB atau morphin 0.1 mg/kgBB, dan obat pelumpuh otot atracurium atau vecuronium atau rocuronium. Rumatan cairan dengan RL 6 – 8 ml/kgBB/jam Diberikan reversal neostigmin dan atropin Anestesi diakhiri, agent inhalasi dihentikan, dan ekstubasi dilakukan setelah pasien bernafas spontan dan adekuat Pemberian analgetik pasca operasi berupa NSAID (misalnya paracetamol iv 10 – 15 mg/kgBB; metamizol iv 10 mg/kgBB) atau Opioid sistemik Peserta ujian melakukan semua item penata laksanaan kegawatan yang meliputi : Menginformasikan kepada operator mengenai terjadinya pneumothorax dan meminta untuk menghentikan operasi dan deflasi peritoneum Dilakukan needle thoracosentesis id ICS 2 linea midclavicularis kanan dengan iv cath ukuran 14G. Konsul Bedah untuk pemasangan WSD Paska operasi pasien dirawat di ICU Peserta ujian menyampaikan tatalaksana pasca anestesia secara lengkap dan benar Paska operasi pasien dirawat di ICU Mode ventilator : CPAP PEEP 3-5, FiO2 30-50% Weaning bertahap Kontrol fungsi WSD Manajemen nyeri dapat diberikan Morfin 10-20 mcg/kgBB/jam atau kombinasi dengan NSAID Antibiotik spesifik gram negatif', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Total Tyroidektomi', 'Anestesi Umum & Regional', 17,
  'Seorang Perempuan 35 tahun direncanakan tindakan operasi total tyrodektomi', 'Lakukan Evaluasi Preoperative \nTentukan Diagnosa dan problem potensial – aktual\nRencana dan lakukan tindakan anestesi dengan intubasi sulit\nPENILAIAN :\nPenguji mengamati dan menilai tindakan preoperatif yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta.\nPeserta menanyakan :\nAnamnese \nberdebar debar(+), TREMOR (+)\nAlergi (-), pada saat tidur mengorok(+)\nMakan minum terakhir 8 jam yl ,\nsudah 1 bulan sering BAB encer\nsebelum MRS, sudah dikelola bagian penyakit dalam\nPemeriksaan Klinis:\nBB 45 kg, TB 157 cm.\nKesadaran Compos mentis GCS15 E4V5M6,\nExophtalmus, pupil isokor 3mm/3mm RC +/+\nLeher: terdapat benjolan sebesar bola tennis dan pergerakan dari leher terbatas.\nFrekuensi nafas 18-20 x/menit, suara pernafasan vesikuler suara tambahan tidak ada, \nTekanan darah 160/90 mmHg, Nadi 105 x/menit, kuat, Jantung : suara jantung normal, Suhu 37oC. \nAbdomen: dbn\nProduksi urine : 60 cc/jam \nPemeriksaan penunjang :\nHasil Laboratorium :\nDarah Rutin : Hb 10,8 gr%, Ht 30%, WBC 9 k/µL, Plt 287 gr/dl\nFaal Hemostasis : PPT10,9  (12,2) , APTT 35,8 (30,7), INR 1,5\nBun (Ureum) : 30 mg/dl, Creatinin 1,1 mg/dl\nNa 147 mmol/L, Kalium 4,3 mmol/L ,Cl 100 mmol/L\nFaal Hati :AST 39, ALT 43, LDH 296, albumin 3,8, globulin 3,42\nHormon tiroid: T3 75 ng/dl (70-190), T4 19,3 ng/dl (5-12), fT4 0,95 ng/dl (0,7-1,55), TSH 8,1 μIU/ml /normal\nGlukosa 98 mg/dl, \nThorak foto : CTR<50% C/P dbn\nCervical foto: deviasi ke lateral dan penyempitan pada trakhea \nEKG : Sinus Takikardia.\nDiagnosa dan problem potensial – aktual. \nDiagnosa : EUTHYROID pro TT\nProblem aktual potensial: \n- difficult airway management\n- kemungkinan badai tiroid\n- kemungkinan komplikasi bull neck dan laringomalasia\nPersiapan preoperative :\nPastikan euvolemia dengan rehidrasi terlebih dahulu\nKontrol tekanan darah : turunkan tekanan darah 20% \nMonitoring Tanda Vital\nIv line besar min no 18, persiapan darah\nPersiapan intubasi sulit: stilet, Mc Coy, LMA, glidescope, cricotyroidektomi, PDT, fiberoptik/bronkoskopi \nPenguji menilai Manajemen anestesi yang dilakukan peserta\nPilihan Anestesi :\nGeneral Anestesi intubasi dengan non apneu\nRencana Tindakan Anestesi :\nMenyiapkan obat anestesi yang diperlukan, mengecek mesin anestesi dan alat monitor pasien, memakai alat pelindung diri (minimal handschoen)\nPersiapan intubasi sulit: stilet, Mc Coy, LMA \nSiapkan 3 ukuran ETT, memilih pipa endotrakeal dengan ukuran lebih kecil : 6 atau 6,5 mm \nInduksi  dengan agen IV cepat ( propofol / etomidate), analgetik (fentanyl), di dalamkan dengan agen inhalasi\nDiberikan ventilasi tekanan positip, bila sudah dalam dan rilex\nIntubasi: mengambil laryngoskop dengan tangan kiri, membuka mulut penderita tanpa ekstensi kepala, menyusuri lidah dari kiri ke kanan hingga tampak epiglotis dan plica vocalis\ninsersi pipa endotrancheal dgn stilet\nkembangkan cuff, \nauskultasi untuk simetrisasi suara napas\nfiksasi',
  ': Penguji mengamati dan menilai tindakan preoperatif yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta. Peserta menanyakan : Anamnese berdebar debar(+), TREMOR (+) Alergi (-), pada saat tidur mengorok(+) Makan minum terakhir 8 jam yl , sudah 1 bulan sering BAB encer sebelum MRS, sudah dikelola bagian penyakit dalam Pemeriksaan Klinis: BB 45 kg, TB 157 cm. Kesadaran Compos mentis GCS15 E4V5M6, Exophtalmus, pupil isokor 3mm/3mm RC +/+ Leher: terdapat benjolan sebesar bola tennis dan pergerakan dari leher terbatas. Frekuensi nafas 18-20 x/menit, suara pernafasan vesikuler suara tambahan tidak ada, Tekanan darah 160/90 mmHg, Nadi 105 x/menit, kuat, Jantung : suara jantung normal, Suhu 37oC. Abdomen: dbn Produksi urine : 60 cc/jam Pemeriksaan penunjang : Hasil Laboratorium : Darah Rutin : Hb 10,8 gr%, Ht 30%, WBC 9 k/µL, Plt 287 gr/dl Faal Hemostasis : PPT10,9 (12,2) , APTT 35,8 (30,7), INR 1,5 Bun (Ureum) : 30 mg/dl, Creatinin 1,1 mg/dl Na 147 mmol/L, Kalium 4,3 mmol/L ,Cl 100 mmol/L Faal Hati :AST 39, ALT 43, LDH 296, albumin 3,8, globulin 3,42 Hormon tiroid: T3 75 ng/dl (70-190), T4 19,3 ng/dl (5-12), fT4 0,95 ng/dl (0,7-1,55), TSH 8,1 μIU/ml /normal Glukosa 98 mg/dl, Thorak foto : CTR<50% C/P dbn Cervical foto: deviasi ke lateral dan penyempitan pada trakhea EKG : Sinus Takikardia. Diagnosa dan problem potensial – aktual. Diagnosa : EUTHYROID pro TT Problem aktual potensial: - difficult airway management - kemungkinan badai tiroid - kemungkinan komplikasi bull neck dan laringomalasia Persiapan preoperative : Pastikan euvolemia dengan rehidrasi terlebih dahulu Kontrol tekanan darah : turunkan tekanan darah 20% Monitoring Tanda Vital Iv line besar min no 18, persiapan darah Persiapan intubasi sulit: stilet, Mc Coy, LMA, glidescope, cricotyroidektomi, PDT, fiberoptik/bronkoskopi Penguji menilai Manajemen anestesi yang dilakukan peserta Pilihan Anestesi : General Anestesi intubasi dengan non apneu Rencana Tindakan Anestesi : Menyiapkan obat anestesi yang diperlukan, mengecek mesin anestesi dan alat monitor pasien, memakai alat pelindung diri (minimal handschoen) Persiapan intubasi sulit: stilet, Mc Coy, LMA Siapkan 3 ukuran ETT, memilih pipa endotrakeal dengan ukuran lebih kecil : 6 atau 6,5 mm Induksi dengan agen IV cepat ( propofol / etomidate), analgetik (fentanyl), di dalamkan dengan agen inhalasi Diberikan ventilasi tekanan positip, bila sudah dalam dan rilex Intubasi: mengambil laryngoskop dengan tangan kiri, membuka mulut penderita tanpa ekstensi kepala, menyusuri lidah dari kiri ke kanan hingga tampak epiglotis dan plica vocalis insersi pipa endotrancheal dgn stilet kembangkan cuff, auskultasi untuk simetrisasi suara napas fiksasi', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Hipertiroid Pada Operasi Darurat /NGT', 'Anestesi Umum & Regional', 17,
  'Seorang Perempuan 32 tahun post KLL direncanakan tindakan operasi cito ORIF pada fraktur terbuka pada lengan kiri bawah. Pasien dengan riwayat penyakit tyroid. Operasi dilakukan dengan General Anestesi. Lakukan pemasangan NGT pada pasien tesebut.', 'Evaluasi Preoperative \nDiagnosa dan problem potensial – aktual\nRencana tindakan anestesi\nKeterampilan klinis\nMonitoring \nManajemen paska bedah\nKomunikasi, edukasi dan profesionalisme\nPENILAIAN :\nPenguji mengamati dan menilai tindakan preoperatif yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta.\nPeserta menanyakan :\nAnamnese \nSymptoms \n     - Dyspnea on effort (+1)\n- Palpitationes (+2)\n- Tiredness (+2)\n- Excessive sweating (+3)\n- Nervousness (+2)\n- Appetite increased (+3)\n- Weight decreased (+3)\nsudah dikelola bagian penyakit dalam dgn terapi:\nPTU 2x100mg\nPropanolol 3x50mg\nPemeriksaan Klinis:\nBB 39 kg, TB 157 cm.\nKesadaran Compos mentis GCS15 E4V5M6,\nExophtalmus, pupil isokor 3mm/3mm RC +/+\nLeher: teraba benjolan sebesar telur ayam, mobile\nFrekuensi nafas 18-20 x/menit, suara pernafasan vesikuler suara tambahan tidak ada, \nTekanan darah 140/90 mmHg, Nadi 105 x/menit, kuat, Jantung : suara jantung normal, Suhu 37,5oC. \nAbdomen: dbn\nProduksi urine : 40 cc/jam \nSign\n- Palpable thyroid ( ada  +3)\n- Exophthalmus ( ada  +2)\n- Hands moist ( ada  +1)\n- Pulse rate more than 90/min ( ada  +3)\nPemeriksaan penunjang :\nHasil Laboratorium :\nDarah Rutin : Hb 12,8 gr%, Ht 30%, WBC 9 k/µL, Plt 276 gr/dl\nFaal Hemostasis : PPT10,9  (12,2) , APTT 35,8 (30,7), INR 1,5\nGlukosa 98 mg/dl, \n         Bun (Ureum) : 48 mg/dl, Creatinin 1,1 mg/dl\n         Na 137 mmol/L, Kalium 4,5 mmol/L ,Cl 109 mmol/L\n         Faal Hati :AST 35, ALT 43, LDH 296, albumin 2,7, globulin   3,42\nHormon tiroid: T3 150 ng/dl (70-190), T4 19,3 ng/dl (5-12), fT4 0,95 ng/dl (0,7-1,55), TSH 0,3 μIU/ml (0,5-6)\nThorak foto : CTR<50% C/P dbn\nCervical foto: tidak ada deviasi trakea, dbn\nEKG : Sinus Takikardia.\nDiagnosa dan problem potensial – aktual. \nDiagnosa : hipertiroid/ pro ORIF  dengan hipertiroid\nProblem aktual potensial: \n- kemungkinan munculnya badai tiroid\n- difficult airway management\nPersiapan preoperative :\nPrinsip penatalaksanaannya adalah mencegah terjadinya “badai tiroid“.\npropanolol intravena 0,5 mg ditingkatkan secara bertahap sampai dengan nadi dibawah 100 kali/menit. \npropylthyouracil 200-400 mg setiap 6 jam atau methimazole 20-40 mg setiap 6 jam\nIntravenous dexamethason 2 mg setiap 6 jam atau hydrocortison 40 mg setiap 6 jam\nPotasium Iodide 5 tetes per-oral setiap 6 jam atau Lugol 30 tetes per-oral setiap 6 jam\nIv line besar, persiapan darah\nPersiapan intubasi sulit : LMA, PDT, fiberoptik/bronkoskopi \nPremedikasi : midazolam 0,05-0,1mg/kgBB\nPencegahan aspirasi pneumonia : 30 ml oral non particulated  antacid + metocloperamide 10 mg iv + H2 blocker iv\nPenguji menilai Manajemen anestesi yang dilakukan peserta\nPemasangan NGT\nPersiapan:\nInformed consent pasien\nPenjelasan prosedur pemeriksaan, indikasi, kontraindikasi/komplikasi\nPersiapan diri :  memakai sarung tangan / APD\nPersiapan alat : menyiapkan alat-alat yang dibutuhkan, NGT, spuit, jelly, stetoskop\nMemperhatikan sterilitas saat pemeriksaan\nPemasangan NGT :\nUkur panjang selang dari mulut melewati telinga terus ke arah perut bagian depan dan lubang terahir dibawah processus xhipoid.\nMemasukkan bagian pangkal selang ke dalam air\nMengolesi selang dengan jelly\nMinta pasien untuk menundukkan kepala dan dengan gentle memasukkan selang kedalam hidung selang sambil meminta pasien untuk  menelan sampai dengan ukuran. \nKonfirmasi pemasangan NGT dengan memasukkan udara 10-20 ml dengan spuit cateter tip sambil didengarkan di regio epigastric dg stetoskop.',
  ': Penguji mengamati dan menilai tindakan preoperatif yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta. Peserta menanyakan : Anamnese Symptoms - Dyspnea on effort (+1) - Palpitationes (+2) - Tiredness (+2) - Excessive sweating (+3) - Nervousness (+2) - Appetite increased (+3) - Weight decreased (+3) sudah dikelola bagian penyakit dalam dgn terapi: PTU 2x100mg Propanolol 3x50mg Pemeriksaan Klinis: BB 39 kg, TB 157 cm. Kesadaran Compos mentis GCS15 E4V5M6, Exophtalmus, pupil isokor 3mm/3mm RC +/+ Leher: teraba benjolan sebesar telur ayam, mobile Frekuensi nafas 18-20 x/menit, suara pernafasan vesikuler suara tambahan tidak ada, Tekanan darah 140/90 mmHg, Nadi 105 x/menit, kuat, Jantung : suara jantung normal, Suhu 37,5oC. Abdomen: dbn Produksi urine : 40 cc/jam Sign - Palpable thyroid ( ada +3) - Exophthalmus ( ada +2) - Hands moist ( ada +1) - Pulse rate more than 90/min ( ada +3) Pemeriksaan penunjang : Hasil Laboratorium : Darah Rutin : Hb 12,8 gr%, Ht 30%, WBC 9 k/µL, Plt 276 gr/dl Faal Hemostasis : PPT10,9 (12,2) , APTT 35,8 (30,7), INR 1,5 Glukosa 98 mg/dl, Bun (Ureum) : 48 mg/dl, Creatinin 1,1 mg/dl Na 137 mmol/L, Kalium 4,5 mmol/L ,Cl 109 mmol/L Faal Hati :AST 35, ALT 43, LDH 296, albumin 2,7, globulin 3,42 Hormon tiroid: T3 150 ng/dl (70-190), T4 19,3 ng/dl (5-12), fT4 0,95 ng/dl (0,7-1,55), TSH 0,3 μIU/ml (0,5-6) Thorak foto : CTR<50% C/P dbn Cervical foto: tidak ada deviasi trakea, dbn EKG : Sinus Takikardia. Diagnosa dan problem potensial – aktual. Diagnosa : hipertiroid/ pro ORIF dengan hipertiroid Problem aktual potensial: - kemungkinan munculnya badai tiroid - difficult airway management Persiapan preoperative : Prinsip penatalaksanaannya adalah mencegah terjadinya “badai tiroid“. propanolol intravena 0,5 mg ditingkatkan secara bertahap sampai dengan nadi dibawah 100 kali/menit. propylthyouracil 200-400 mg setiap 6 jam atau methimazole 20-40 mg setiap 6 jam Intravenous dexamethason 2 mg setiap 6 jam atau hydrocortison 40 mg setiap 6 jam Potasium Iodide 5 tetes per-oral setiap 6 jam atau Lugol 30 tetes per-oral setiap 6 jam Iv line besar, persiapan darah Persiapan intubasi sulit : LMA, PDT, fiberoptik/bronkoskopi Premedikasi : midazolam 0,05-0,1mg/kgBB Pencegahan aspirasi pneumonia : 30 ml oral non particulated antacid + metocloperamide 10 mg iv + H2 blocker iv Penguji menilai Manajemen anestesi yang dilakukan peserta Pemasangan NGT Persiapan: Informed consent pasien Penjelasan prosedur pemeriksaan, indikasi, kontraindikasi/komplikasi Persiapan diri : memakai sarung tangan / APD Persiapan alat : menyiapkan alat-alat yang dibutuhkan, NGT, spuit, jelly, stetoskop Memperhatikan sterilitas saat pemeriksaan Pemasangan NGT : Ukur panjang selang dari mulut melewati telinga terus ke arah perut bagian depan dan lubang terahir dibawah processus xhipoid. Memasukkan bagian pangkal selang ke dalam air Mengolesi selang dengan jelly Minta pasien untuk menundukkan kepala dan dengan gentle memasukkan selang kedalam hidung selang sambil meminta pasien untuk menelan sampai dengan ukuran. Konfirmasi pemasangan NGT dengan memasukkan udara 10-20 ml dengan spuit cateter tip sambil didengarkan di regio epigastric dg stetoskop.', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Manajemen Adenotnsilektomi Pediatrik', 'Anestesi Pediatrik', 17,
  'Anak usia 7 tahun, berat badan 40 kg, tinggi badan 110 cm, direncanakan akan operasi adenotonsilektomi elektif dengan riwayat asma.', 'Lakukan evaluasi preoperative\nSebutkan diagnosa dan problem potensial – aktual	\nSebutkan dan lakukan rencana tindakan anestesi\nSebutkan Manajemen paska tindakan bedah',
  ': Penguji mengamati dan menilai tindakan preoperatif yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta. Peserta menanyakan : Anamnese Alergi (+) dingin dan makanan laut, Pengobatan (+) salbutamol spray, Riwayat penyakit dahulu (+) asma, serangan terakhir 3 bulan yang lalu membaik dengan pemberian spray Makan terakhir : puasa 6 jam sebelum operasi Riwayat penyakit sekarang : tidur mendengkur, suka mengantuk di kelas, sesak malam (+), bernafas lewat mulut Pemeriksaan Klinis: BB 40 kg, TB 110 cm. Kesadaran Compos mentis GCS15 E4V5M6, Tanda vital : Tekanan darah 90/50 mmHg, Nadi 90 x/menit, kuat angkat, Frekuensi nafas 25 x/menit, Suhu 37oC Pupil isokor 3mm/3mm RC +/+ Mulut: Mallampati 3 Leher: tidak teraba limfonodi, TMD = 2 jari dewasa Auskultasi paru : suara pernafasan vesikuler suara tambahan tidak ada Jantung : bunyi jantung I-II normal, Abdomen: supel, hepar lien tidak teraba Ekstremitas : dalam batas normal Pemeriksaan penunjang : Hasil Laboratorium : Darah Rutin : Hb 12 gr%, Ht 36%, WBC 8 k/µL, Plt 300 gr/dl PPT 10,9 (11,2) , APTT 35,8 (36,7) Ureum : 49 mg/dl, Creatinin 0,3 mg/dl Na 135 mmol/L, Kalium 4,0 mmol/L , Cl 99 mmol/L Albumin 3,5 Glukosa 90 mg/dl, Thorak foto : CTR<50% C/P dbn EKG : Sinus Ritme 90x/menit Diagnosa dan problem potensial – aktual. Diagnosa : Adenotonsilitis kronis Obesitas Asma terkontrol Obstructive Sleep Apneu Problem aktual dan potensial : difficult airway management serangan asma lambat bangun perdarahan pasca bedah Persiapan preoperative : Premedikasi untuk pasien alergi dengan antihistamin dan steroid Persiapan intubasi sulit Penguji menilai Manajemen anestesi yang dilakukan peserta PilihanAnestesi : General Anestesi intubasi Rencana Tindakan Anestesi : STATIC, menyiapkan obat anestesi yang diperlukan, mengecek mesin anestesi dan alat monitor pasien, memakai alat pelindung diri (minimal handschoen) Siapkan 3 ukuran ETT, memilih pipa endotrakeal dengan ukuran lebih kecil Induksi yang dalam dengan agen IV cepat ( propofol / etomidate ), analgetik (fentanyl), dan Muscle relaxan non histamine release dengan Vecuronium Diberikan ventilasi tekanan positip, bila sudah dalam dan rilex mengambil laryngoskop dengan tangan kiri, membuka mulut penderita dengan ekstensi kepala, menyusuri lidah dari kanan ke kiri hingga tampak epiglotis dan plica vocalis insersi pipa endotracheal kembangkan cuff, auskultasi untuk simetrisasi suara napas, fiksasi Mampu melakukan teknik rumatan anestesi umum dengan volatile anestesi halothane Penguji menilai manajemen paska operative yang disebutkan dan ditulis peserta Ekstubasi dilakukan pada saat pasien nafas adekuat dan sadar penuh Pasien di rawat di PACU Monitoring tanda vital dan saturasi oksigen dan kemungkinan munculnya komplikasi perdarahan, serangan asma pasca operasi Bila perlu diberikan inhibitor kolinesterase dan nalokson Pilihan utama analgesia sistemik non opioid dengan parasetamol', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Anestesi Umum Pada Labiopalatoschizis', 'Anestesi Pediatrik', 17,
  'Seorang bayi perempuan berusia 3 bulan, berat badan 6 kg. Didiagnosa dengan Labiopalatoshizis akan dilakukan tindakan Labioplasty.', '1. Lakukan evaluasi preoperatif terhadap pasien tersebut\n2. Sebutkan Problem potensial dan aktual terhadap pasien tersebut\n3. Sebutkan persiapan anestesi pada pasien tersebut\n4. Lakukan tindakan intubasi pada pasien tersebut',
  ': 1. Penguji mengamati dan menilai evaluasi preoperatif yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta. Peserta ujian menanyakan : Riwayat kelahiran, makan minum, ispa, tersedak dan sianosis Riwayat penyakit terdahulu tidak ada Pemeriksaan fisik : airway clear, Frekuensi nafas 26 x/menit, suara pernafasan vesikuler, Nadi 130 x/menit, Murmur (-), Menangis kuat, Temp 36,8 C Pemeriksaan penunjang : Darah Rutin : Normal , Foto Thorax : Normal Informed concent :Tindakan anestesi yang akan dilakukan dan komplikasinya 2. Penguji mengamati dan menilai Problem potensial dan problem actual Problem actual : Difficult Airway Management Problem Potensial : Laringospasm, Bradicardia, Desaturasi 3. Penguji mengamati dan menilai persiapan anestesi pada pasien tersebut Rencana Anestesi : Puasa 6 jam Anestesi : General Anestesi sleep apnu atau sleep non apnu Tehnik Anestesi : Semi Open ETT 2,5 3 3,5 Premedikasi : Dexamethason 0,1 – 0,5 mg/kg, Atropin 0,01 – 0,02 mg/kg, minimal 0,1 mg Pelumpuh otot : Atracurium 0,5 mg/kg, Rocuronium 0,6 – 1,2 mg/kg, Vecuronium 0,1 mg/mg Induksi : Intravena agent, Inhalation agent (Slow Induction) Pemeliharaan : O2 NO2 Sevoflurane/ Isoflurane/ Halothan Monitoring : Tanda Vital setiap 5 menit, kedalaman anestesi, perdarahan 4. Penguji mengamati dan menilai tindakan intubasi pada bayi Mencuci tangan dan menggunakan sarung tangan Menyiapkan alat (STATICS), bantal intubasi, alat bantu nafas (Guedel, stylet, dll), memeriksa kondisi mesin anestesi dan mempersiapkan obat-obatan Monitor tanda – tanda vital (Irama ECG, Tekanan darah, Nadi, saturasi oksigen, Respirasi rate) Memeriksa ulang kondisi kemudahan intubasi (Mallampatti, Jarak mento-hyoid, gerak leher) Diberikan (diinstruksikan) obat premedikasi Pasien supine, sniffing position, kepala pasien setinggi processus xiphoideus Gunakan Jacson Rees, buka O2 6L/menit untuk preoksigenasi Diberikan (diinstruksikan) obat induksi, bila induksi dengan inhalasi maka FGF = O2 : N2O = 3 : 3 L/menit, dipastikan ventilasi positif bisa dilakukan Diberikan (diinstruksikan) obat pelumpuh otot Menunggu onset obat pelumpuh otot sambil dilakukan preoksigenasi Memegang laringoskop dengan tangan kiri, melakukan ekstensi kepala dan memasukkan blade kedalam mulut dari sisi kanan menyisir lidah ke kiri Melihat pita suara secara avue, dan memasukkan ETT dengan tangan kanan dengan smooth Mengembangkan cuff, memastikan suara paru kiri sama dengan kanan Melakukan fiksasi ETT dengan baik Mencuci tangan', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Hernia Inguinalis Lateralis (Hil) Dupleks', 'Anestesi Pediatrik', 17,
  'Bayi laki-laki usia 5 bulan, berat badan 5 kg. Didiagnosa dengan HIL Duplex ireponibilis akan dilakukan tindakan Laparatomi cito.', 'Lakukan evaluasi preoperatif terhadap pasien tersebut\nSebutkan diagnosa, Problem potensial dan aktual terhadap pasien tersebut\nSebutkan persiapan anestesi pada pasien tersebut\nLakukan manajemen anestesi pada pasien tersebut\nInstruksi pada penguji  \n1. Penguji mengamati dan menilai evaluasi preoperatif yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta.\nPeserta ujian menanyakan :\nRiwayat alergi, riwayat medikasi sebelumnya  tidak ada\nRiwayat kelahiran (normal), last meal (8 jam ASI), ispa (tidak ada)\nRiwayat penyakit terdahulu tidak ada\nEvent: muntah terus menerus warna hijau dan benjolan di inguinal tidak dapat dimasukkan sejak 6 jam SMRS\nPemeriksaan fisik : letargi dan iritabel,  Temp 38,8 C, Skor FLACC 6 \nairway clear, Frekuensi nafas 40 x/menit, suara pernafasan vesikuler, TD : 60/30 mmHg, Nadi 130x/menit teraba lemah, Murmur (-), ubun-ubun tampak cekung, abdomen distended, Mukosa tampak kering, CRT 4 detik\nlokalis : HIL duplex ireponibel\nPemeriksaan penunjang : \nDarah Rutin : Hb 14; Ht 45; AL 17000; AT 165000; Elektrolit : Na 130; K 2,8; Cl 100\nFoto Thorax : Normal\n2. Penguji mengamati dan menilai Problem potensial dan problem actual\n    Diagnosa             : Bayi laki-laki 5 bulan berat badan 5 kg dengan diagnosa HIL Duplex Ireponibel pro laparotomi rencana General anestesi RSI status fisik ASA 3E\n Problem actual     : Infant, Dehidrasi, lambung penuh, nyeri\n     Problem Potensial : Syok, Gangguan keseimbangan elektrolit, aspirasi, desaturasi, laringospasme\n3. Penguji mengamati dan menilai persiapan anestesi pada pasien tersebut\n     Persiapan Anestesi:\nInformed consent\nPaska operasi sedia PICU\nPuasa dilanjutkan\nPemasangan OGT untuk dekompresi lambung \nBerikan analgetik paracetamol 100 mg (dosis 20 mg/kg) intravena\nPasang kateter urine (bila diminta peserta ujian)  urine output 3 cc/jam\nPemasang iv line  lakukan rehidrasi pada pasien:\nPasien dalam kondisi dehidrasi sedang  defisit cairan 100 cc/kg (500 cc): rehidrasi bertahap dengan cairan ringer laktat 20-30 cc/kg dalam waktu 30 menit- 1jam  cek tanda vital hemodinamik dan urine output; bila belum stabil ulangi rehidrasi. Bila telah stabil berikan cairan 10 cc/kg/jam hingga urine output >1 cc/kg/jam \n4. Manajemen Anestesi\nPremedikasi : Dexamethason 0,1 – 0,5 mg/kg, Metoclopramide 0,15 mg/kg, Ranitidine 0,25-1 mg/kg\nRehidrasi dilanjutkan dan lakukan aspirasi OGT untuk mengosongkan isi lambung\nPersiapan ruangan dengan pemasangan warmer\nCuci tangan dan pakai APD\nLakukan RSI dengan teknik 7P:\nPreparasi mesin, alat,dan obat\nPreoksigenasi dengan oksigen 100% selama 3 menit\nPretreatment dengan Atropin 0,02 mg/kg, Fentanyl 2 mcg/kg\nParalisis with induction dengan Ketamin 2 mg/kg + Rocuronium 1,2 mg/kg\nPositioning dan sellick manuver\nPlacement with proof\nPost intubation management\nMaintenance Anestesi:\nVentilasi kendali dengan udara tekanan 50% dalam oksigen dengan agen anestesi menggunakan  Sevofluran 2-3 vol%. \nMaintenance analgetik (fentanyl) dan agen pelumpuh otot (rocuronium) sesuai kebutuhan\nPost operasi:\nPasien diekstubasi sadar penuh\nPaska operasi dirawat di ICU\nAnalgetik paska operasi Paracetamol 100 mg/8 jam (20mg/kg/8jam)',
  'Pastikan identitas peserta ujian. Amati dan berikan skor sesuai rubrik penilaian.', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Gagal Nafas + Syok Kardiogenik', 'Resusitasi & Critical Care', 17,
  'Skenario klinis tidak tersedia.', 'Lakukan tindakan sesuai instruksi penguji.',
  'Penguji mengamati dan menilai penampilan peserta berdasarkan lembar penilaian Penguji memberikan kertas berisi informasi mengenai pasien, yang berisi Initial Assessment: Jalan nafas bebas, snooring/gargling/crowing: -/-/- Frekwensi napas 35 kali/menit, rektrasi iga (+), sianosis, pernafasan cuping hidung, ronchi basah (+) seluruh lapangan paru, SpO2 82% (oksigen 12 ltr/mnt via NRM) Perfusi dingin/basah/pucat, nadi 130 kali/menit teraba halus, tekanan darah 70/40 mmHg, tampak vena jugular distensi Kesadaran somnolen, pupil isokor, RC (+/+) simetris Telah terpasang foley kateter, dengan produksi urine (-) Abdomen soepel, bising usus (+) normal Dijumpai oedem pada ekstremitas bawah Penguji menjawab hasil pemeriksaan penunjang (hanya jika diminta oleh peserta!) dan menilai interpretasi yang dilakukan oleh peserta uji! Pemeriksaan Penunjang: AGDA : pH: 7.15, PaO2: 47, PaCO2: 50, HCO3: 12, BE: -12, SaO2: 85% Interpretasi:Kombinasi Asidosis metabolik dan respiratorik dengan hipoksemia Penguji memberikan foto thoraks pada peserta ujian Interpretasi: Cardiomegaly dan Edema Paru Darah rutin:Hb: 9 gr/dl, Leukosit: 15.000, Platelet:138.000/ml3 Interpretasi:Anemia, leukositosis Laktat:5mmol/L Interpretasi:Hiperlaktanemia Penguji memberikan hasil EKG pada peserta ujian Interpretasi:OMI Anteroseptal Penguji menilai diagnosis klinis Diagnosis Klinis : Gagal Napas Tipe 1 dan 2 Syok Kardiogenik Edema Paru Akut Penguji menilai kemampuan peserta ujian dalam tatalaksana dan setting ventilator Non-Farmakologis: Intubasi dengan teknik RSI Setting ventilator :Mode Pressure/ Volume Control Ventilation, Predicted Body Weight: 60 Kg, TV:240-360 ml, MV: 6 liter, RR: 20 x/mnt, PEEP: ≥ 8 cmH2O, I:E ratio 1:2, FiO2: 100%, P.Plateau: <30 cmH20 Farmakologis: Restriksi Terapi cairan Inotropik Diuretik Sedasi dan Analgesia Nutrisi Stress Ulcer Prevention Glucose Control Thromboembolitic Prophylaxis', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'TURP', 'Anestesi Umum & Regional', 17,
  'Seorang laki-laki berusia 69 tahun, dibawa ke ruang pulih setelah menjalani operasi TURP selama 90 menit dalam anestesi umum. Dua puluh menit kemudian, pasien telah sadar namun tampak gelisah dan mengeluh sakit kepala. Dari penilaian preanestesi diketahui bahwa pasien ini dengan ASA II geriatri.', 'Lakukan evaluasi pasien ini\nTentukan pemeriksaan penunjang, diagnosis banding dan diagnosis utama\nSebutkan manajemen diagnosis pada kasus ini',
  'preanestesi diketahui bahwa pasien ini dengan ASA II geriatri. Instruksi untuk peserta : Lakukan evaluasi pasien ini Tentukan pemeriksaan penunjang, diagnosis banding dan diagnosis utama Sebutkan manajemen diagnosis pada kasus ini INSTRUKSI KHUSUS : Penguji mengamati dan menilai apa yang dievaluasi oleh peserta ujian: Airway clear Frekuensi napas 40 x/menit, SpO2 92% dengan simpel mask 10 l/menit Tekanan darah 140/90 mmHg, denyut nadi 60 x/menit Kesadaran CM (gelisah) Suhu aksila 35,5 oC Kualitas nadi: isi dan tegangan cukup Vena jugularis: tidak distensi Paru: ronkhi basah di basal paru Jantung: tidak ada S3 gallop Abdomen: distensi tidak ada, lemas, nyeri tekan tidak ada Akral dingin Penguji menilai peserta menentukan: Diagnosis banding Perdarahan Sindroma', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Tumor Payudara', 'Anestesi Rawat Jalan & NORA', 17,
  'Skenario klinis tidak tersedia.', 'Lakukan tindakan sesuai instruksi penguji.',
  'Penguji mengamati dan menilai tindakan pra anestesia yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang (hanya bila diminta oleh peserta!) Penguji menilai kemampuan peserta untuk melakukan anamnesis dan pemeriksaan fisik: Anamnesis :Alergi obat ibuprofen, antalgin, asam mefenamat, ketorolak. Medication : Nebulizer ventolin 3 bulan lalu. Past illness : Riwayat asma, terakhir kambuh 3 bulan yang lalu dengan terapi nebulizer ventolin. Last Meal : 10 jam sebelum operasi, Event : (-) Vital Sign : Tensi 130/80mmHg, HR 68 x/menit, RR 12-14x/menit, Temp 36.5oC VAS Diam 0/100 mm dan VAS bergerak 0/100 mm. BB 50kg, TB 170cm. Airway : LEMON SCORE BAIK (Look externally, Evaluate, Mallampati, Obstruction, Neck mobility) Paru-paru : Vesikuler +/+, Ronkhi -/-, Wheezing -/- Pemeriksaan fisik lain : dalam batas normal Hasil Lab : Darah Rutin : Hb 12.8gr%, Hct 36.5, WBC 6100 gr%, Plt 169000 gr%. Kandidat mampu melakukan identifikasi problem actual-potensial: Problem aktual: Kecemasan karena pasien wanita muda Seorang penyanyi. Problem potensial : Asma kambuh, alergi obat, gangguan pada pita suara, nyeri pasca operasi, PONV Peserta ujian saat melakukan tugas informed consent, harus melakukan dengan serius. Diagnosis kerja Dasar diagnosis dan kondisi pasien Tindakan anestesi yang akan dilakukan Prosedur tindakan Tujuan tindakan Resiko tindakan Efek samping obat Komplikasi tindakan Alternatif dan resiko Memberikan kesempatan kepada pasien dan atau keluarga untuk bertanya Memberikan umpan balik yang baik atas pertanyaan pasien dan atau keluarga Memperkenalkan diri dan mengucapkan salam', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Trauma Dan Emergensi', 'Resusitasi & Critical Care', 17,
  'Seorang laki-laki 35 tahun, BB 70 kg, dibawa ke IGD setelah mengalami kecelakaan lalu lintas mengendarai mobil dengan kecepatan tinggi dan menabrak tiang listrik setelah menghindari pejalan kaki. Pasien mengeluh sesak karena dadanya terbentur stir mobil.', 'Lakukan Initial assesment / primary survey untuk pasien ini\nTentukan prosedur klinis untuk penunjang diagnosis\nTentukan diagnosis klinis\nLakukan tatalaksana dan monitoring',
  'Penguji mengamati dan menilai penampilan peserta berdasarkan lembar penilaian. Penguji menilai kemampuan peserta untuk melakukan pemeriksaan fisik Initial Assessment A: Airway clear, pasien mengerang kesakitan B: Frekwensi napas 35 kali/menit, Saturasi oksigen 85 %, sianosis, deviasi trakea ke kiri, distensi vena jugularis kanan, jejas di dada kanan, gerakan dinding dada asimetris (kanan tertinggal), hipersonor hemithoraks kanan, suara nafas vesikuler kanan menghilang, bunyi jantung menjauh C: Tekanan darah 80/50 mmHg, Laju nadi 140 kali/menit, teraba halus, akral dingin. D: Pasien tampak gelisah, respon dengan rangsangan verbal. GCS E3M6V5, pupil isokor RC +/+ kanan = kiri E: Temperatur 36 oC Penguji memberitahukan data pemeriksaan fisik dan laboratorium sesuai skenario. Penguji menilai diagnosis klinis Diagnosis Klinis : Trauma Tumpul Thoraks dengan komplikasi Tension Pneumothoraks Penguji menilai kemampuan peserta ujian dalam tatalaksana Pemberian oksigen dengan sungkup muka nonrebreathing 10 liter permenit Melakukan needle dekompresi pada hemithoraks kanan ICS 2 linea midklavikula dengan menggunakan jarum infus berukuran besar Memonitoring keberhasilan tindakan needle dekompresi dengan melihat: Frekuensi napas menurun Saturasi oksigen mengalami peningkatan Sianosis berkurang atau menghilang Tidak ada lagi deviasi trakea dan distensi vena jugularis Gerakan dinding dada mulai simetris Suara vesikuler mulai terdengar pada hemithoraks kanan Tekanan darah mulai meningkat Melakukan pemeriksaan penunjang rontgen thoraks', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Gagal Nafas', 'Resusitasi & Critical Care', 17,
  'Seorang laki-laki 60 tahun Panjang badan 64 inci, masuk ICU dirujuk dari RS luar dengan keluhan penurunan kesadaran. 3 hari yang lalu pasien menjalani laparotomi kausa peritonitis', 'Lakukan Initial assesment untuk pasien ini\nTentukan prosedur klinis untuk penunjang diagnosis\nTentukan diagnosis klinis\nLakukan tatalaksana farmakologis dan nonfarmakologis serta monitoring',
  ': Penguji mengamati dan menilai penampilan peserta berdasarkan lembar penilaian. Penguji menilai kemampuan peserta untuk melakukan pemeriksaan fisik Pasien tampak gelisah, respon dengan rangsangan nyeri. Sensorium somnolen, pupil isokor RC +/+ kanan = kiri Airway clear, Frekwensi napas 35 kali/menit, rektrasi iga, sianosis, pernafasan cuping , suara nafas vesikuler mengeras, rochi basah (+) Tekanan darah 80/50 mmHg, Laju nadi 120 kali/menit teraba halus, akral dingin. Temperatur 39 C Saturasi oksigen 92 % dengan oksigen 12 ltr/mnt NRM, Penguji memberitahukan data pemeriksaan fisik dan laboratorium sesuai skenario. Penguji memberikan hasil pemeriksaan penunjang Hb : 9 gr/dl, Lekosit 24.000. Platelet :80.000/ml3. Lactat 4 mmol/L Anemia, leukositosis, trombositopeni AGD : pH : 7.2, PaO2 : 50, PaCO2 : 25, HCO3 : 18, BE: -6 Pembacaan AGD : Asidosis metabolik kompensasi alkalosis respiratorik dengan hipoksemia. Penguji menilai diagnosis klinis Diagnosis Klinis : Syok sepsis dengan gagal napas tipe 1 (hipoksemia) Penguji menilai kemampuan peserta ujian dalam tatalaksana nonfarmakologi dan farmakologi Nonfarmakologis : Lakukan intubasi teknik RSI detail disebutkan mengenai apa yg harus disebutkan peserta Setting ventilator : Initial setting ventilator : Mode Pressure/volume control ventilation, Predicted body weight : 60 KG. TV : 360 ml, RR : 12 X/mnt, PEEP : 5, I:E ratio 1:2, FiO2 100%. Penilaian klinis/monitoring setelah setting awal ventilator Tekanan darah 110/60 mmHg, Nadi 100 x/i, akral dingin, Temperature 37,5 C Sp O2 96%, UOP 40 cc/jam. AGD Farmakologis : Terapi cairan Antibiotic Sedasi dan Analgesi Nutrisi Stress Ulcer prevention Glucose control Thromboembolitic prophylaxis Head of bed Elevation Penyulit/komplikasi : DOPE Dislodge Obstruction Pneumothorax Equipment failure Hipotensi (kekurangan cairan dan efek obat,setting ventilator ) antisipasi nilai status volume dan pemberian cairan Antisipasi evaluasi ulang setting ventilator ( TV ekspirasi, PEEP, I:E ratio)', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Ketoasidosis Diabetik', 'Resusitasi & Critical Care', 17,
  'Skenario klinis tidak tersedia.', 'Lakukan anamnesis \nLakukan pemeriksaan fisik\nUsulkan pemeriksaan penunjang untuk menegakkan diagnosis\nTentukan diagnosis kerja dan diagnosis banding\nBerikan penatalaksanaan pada pasien ini',
  'Anamnesis Riwayat penyakit sekarang : • Keluhan utama : lemas • Sejak kapan : 3 hari • Perjalanan penyakit : 3 hari sebelum masuk RS pasien mengeluh lemas, lemas dirasakan terus menerus, semakin lama semakin memberat dan di seluruh tubuh. Lemas membuat pasien tidak dapat bekerja. muntah (-), mual (+), keringat dingin (-) BAK dirasa lebih sering dibanding kondisi biasanya, nyeri saat buang air kecil (-), anyang anyangan (-)nafsu makan menurun (-) BAB tidak ada keluhan • Keluhan lain terkait keluhan utama : Sesak nafas Mual (+) tanpa disertai muntah Kaki kanan sering kesemutan (+) • Hal-hal yang memperberat keluhan : Lemah diperberat dengan aktivitas seperti berjalan • Hal-hal yang meringankan keluhan : rasa lemas berkurang bila digunakan untuk istirahat • Riwayat pengobatan sekarang : Lupa menyuntikkan insulin Riwayat penyakit dahulu : Riwayat sakit kencing manis (+) diketahui sejak usia 6 tahun, Menggunakan suntikan insulin R 18-0-18 unit Riwayat hipertensi (-) Riwayat badan kegemukan (-) Riwayat mondok tahun 2013: dirawat di RS karena gejala yang sama Riwayat mondok tahun 2014: dirawat di RS sebanyak 2x karena gejala yang sama Riwayat penyakit keluarga : • Riwayat orang tua sakit gula pada ibu penderita Riwayat sosial : • Penderita bekerja sebagai pelayan toko. Biaya pengobatan ditanggung oleh BPJS Pemeriksaan fisik KU : tampak lemah, kesadaran somnolen nafas cepat dan dalam T : 120/80 mmHg, pernafasan : 24 x/ menit nadi : 100 x/menit suhu : 37,9C Status gizi : normoweight Kepala : Rambut mudah rontok (-), turgor dahi kurang Kulit : Turgor kulit kurang Mata : Konjungtiva palpebra pucat (-/-), sklera ikterik (-/-) Hidung : Nafas cuping (-/-) Telinga : Sekret (-), nyeri tekan tragus (-/-) Mulut : Bibir kering, mukosa mulut kering, nafas berbau buah-buahan Tenggorok : Sekret (-),faring hiperemis (-) Leher : Trakea ditengah, JVP R + 0 cm, pembesaran nll (-) Dada : Bentuk normal Paru- paru I : simetris statis dinamis Pa : stem fremitus kanan = kiri Pe : sonor seluruh lapangan paru Au : SD vesikuler (+/+), Suara tambahan (-/-) Jantung : I : Normal Pa : Normal Pe : Normal Au : HR 100 x/menit, BJ I-II reguler, bising (-), gallop (-) Abdomen I : Normal Au : BU (+) N Pe : timpani, PS (+)N, PA (-), area troube timpani Pa : supel, Hepar & Lien tak teraba Extremitas Kaki kanan sering kesemutan (+) Hasil pemeriksaan penunjang (laboratorium) (Hasil dibacakan HANYA jika peserta mengusulkan pemeriksaan tersebut) Hematologi rutin Hb : 13,9 gr% Ht : 41 % Lekosit : 11.000 / uL Trombosit : 250.000/uL Pemeriksaan Kadar Gula GDS : 380 mg/dL Pemeriksaan Kimia lain Ureum : 20 mg/dL (N : 15 – 39 mg/dL) Kreatinin : 0,85 mg/dL (N : 0,6 – 1,3 mg/dL) Elektrolit : Na : 140 mmol/L (N : 136-145 mmol/L) K : 3,0 mmol/L (N : 3,5 – 5,1 mmol/L) Cl : 110 mmol/L (N : 98 – 107 mmol/L) Pemeriksaan urin : Warna : kuning, jernih BJ : 1,025 pH : 5,0 Aceton : positif (3) Reduksi : positif (4) Diagnosis kerja :', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Manajemen Penyulit Kegawatdaruratan', 'Anestesi Umum & Regional', 17,
  'Laki-laki 52 tahun dibawa ke IGD dengan ambulan setelah terluka akibat kebakaran rumah. Lukanya terdapat pada kedua lengan atas, seluruh badan bagian depan dan paha kanan. Tanda vitalnya HR 115 x/menit, frekuensi napas 25 x/menit, tekanan darah 158/92 mmHg dan saturasi 93% menggunakan oksigen nasal kanul. Pada saat mengeluh nyeri, suara pasien terdengar parau dan terbatuk-batuk dengan dahak kehitaman. Direncanakan akan dilakukan tindakan debridement luka.', 'Lakukan evaluasi preoperative\nSebutkan diagnosa dan problem potensial – aktual	\nSebutkan dan lakukan rencana tindakan anestesi',
  ': Penguji mengamati dan menilai tindakan preoperatif yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta. Peserta menanyakan : Anamnese Alergi (-), Medication (-), Past illness (-), Last eaten (baru saja makan dan minum sebelum kebakaran), Event (-) Pemeriksaan Klinis: BB 52 kg, TB 168 cm. Kesadaran Compos mentis GCS15 E4V5M6, Pupil isokor 3mm/3mm RC +/+, bulu mata habis terbakar Leher: tidak teraba limfonodi, luka bakar Frekuensi nafas 25 x/menit, suara pernafasan vesikuler suara tambahan tidak ada, bersuara parau dan batuk saat mengeluh sakit Tekanan darah 158/92 mmHg, Nadi 115 x/menit, kuat, Jantung : suara jantung normal, Suhu 37oC. Abdomen: luka bakar Produksi urine : urine pekat Pemeriksaan penunjang : Hasil Laboratorium : Darah Rutin : Hb 15,1 gr%, Ht 51%, WBC 12 k/µL, Plt 200 gr/dl Faal Hemostasis : PPT10,9 (12,2) , APTT 35,8 (30,7) Bun (Ureum) : 78 mg/dl, Creatinin 1,0 mg/dl Na 148 mmol/L, Kalium 5,2 mmol/L ,Cl 100 mmol/L Faal Hati :AST 189, ALT 163, albumin 3,0, globulin 3,42 Glukosa 90 mg/dl, Thorak foto : CTR<50% C/P dbn EKG : Sinus Takikardia. Diagnosa dan problem potensial – aktual. Diagnosa : Luka Bakar Derajat II Problem aktual potensial: - difficult airway management - lambung penuh - kemungkinan dehidrasi Persiapan preoperative : Pastikan euvolemia dengan rehidrasi terlebih dahulu (memahami rule of nine dan Formula Baxter) Pencegahan aspirasi pneumonia : 30 ml oral non particulated antacid + metocloperamide 10 mg iv + H2 blocker iv Persiapan intubasi pada lambung penuh ( 7P: Preparation, Preoxygenation, Pretreatment, Paralysis, Protection, Placement, Post intubation management) Penguji menilai Manajemen anestesi yang dilakukan peserta PilihanAnestesi : General Anestesi intubasi dengan RSI Rencana Tindakan Anestesi : STATIC, menyiapkan obat anestesi yang diperlukan, mengecek mesin anestesi dan alat monitor pasien, memakai alat pelindung diri (minimal handschoen) Siapkan 3 ukuran ETT, memilih pipa endotrakeal dengan ukuran lebih kecil : 6 atau 6,5 mm Induksi yang dalam dengan agen IV cepat ( propofol / etomidate ), analgetik (fentanyl), dan bila ada Muscle relaxan kerja cepat Rocuronium 1 mg/kgbb Diberikan ventilasi tekanan positip, bila sudah dalam dan rilex mengambil laryngoskop dengan tangan kiri, membuka mulut penderita tanpa ekstensi kepala, menyusuri lidah dari kiri ke kanan hingga tampak epiglotis dan plica vocalis insersi pipa endotracheal kembangkan cuff, auskultasi untuk simetrisasi suara napas, fiksasi Mampu melakukan teknik rumatan anestesi umum dengan volatile anestesi Penguji menilai manajemen paska operative yang disebutkan dan ditulis peserta Monitoring hemodinamik dan kemungkinan munculnya komplikasi Pilihan utama analgesia sistemik opioid intravena menggunakan syringe pump Disarankan menggunakan PCA karena pemberian dosis opioid intravena lebih mencerminkan kebutuhan pasien.', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Krikotiroidotomi', 'Resusitasi & Critical Care', 17,
  'Seorang laki-laki 35 tahun datang ke UGD dengan keluhan nyeri perut kanan bawah sejak 6 jam SMRS. Dari pemeriksaan fisik dan penunjang oleh TS bedah didapatkan diagnosa appendisitis akut yang direncanakan tindakan operasi appendiktomi cito. Pasien direncanakan untuk tindakan anestesi umum dengan intubasi endotrakea. Saat diintubasi ternyata mengalami kesulitan dan pasien jatuh ke dalam situasi can not intubate, can not ventilate. Sehingga dilakukan tindakan krikotiroidotomi emergensi. Peserta harus menjelaskan langkah-langkah dalam algoritme intubasi sulit sampai tindakan emergency invasive airway access dengan needle krikotiroidotomi.', 'Lakukan evaluasi preoperatif.\nTentukan diagnosis, problem aktual-potensial, dan persiapan preoperatif.\nTentukan rencana tindakan anestesi, kemungkinan komplikasi dan penanganannya.\nTentukan manajemen paska bedah',
  ': Penguji mengamati dan menilai evaluasi preoperatif yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta. Peserta menanyakan : Anamnesa A : alergi: (-) M: Medikasi: (-) P: Past illness: (-) L: last meal: 6 jam SMRS E: event: appendisitis akut PemeriksaanKlinis: BB 83 kg, TB 157 cm, BMI 83 kg/m2 KesadaranCompos mentis GCS 15 E4V5M6 A: buka mulut 3 jari, malampati 3, leher pendek, TMD > 6 cm, gerak leher bebas. Tampak benjolan di leher sebelah kanan, diameter 5 cm, tidak ada tanda-tanda radang. B: RR: 18x/menit SpO2: 99% udara bebas, suara dasar vesikuler di kedua lapang paru, tidak ada suara tambahan C: Tekanan darah 123/72 mmHg, Nadi 88 x/menit, kuat, Jantung : suara jantung normal, Suhu 37oC, CRT < 2 detik Abdomen:datar, nyeri tekan perut kanan bawah, defans (+) Produksi urine : 60 cc/jam Pemeriksaan penunjang : Hasil Laboratorium : Darah Rutin : Hb12,8 gr%, Ht 36%, WBC 18 k/µL, Plt 287 gr/dl Faal Hemostasis : PT10,9 (12,2) , APTT 29,8 (30,7), INR 0,9 Bun (Ureum) : 34 mg/dl, Creatinin 0,9 mg/dl Na 137mmol/L, Kalium 4,3mmol/L ,Cl 100mmol/L Glukosa 98 mg/dl, Thorak foto : CTR<50% C/P dbn EKG : Sinus rhytme HR 88, normoaksis Diagnosis, problem aktual–potensial, persiapan preoperatif Diagnosis anestesiologi: laki-laki, 35 tahun dengan apendisitis akut pro laparotomi apendiktomi cito dengan status fisik ASA II, rencana GA intubasi oral, respirasi kontrol. Problem aktual: - akut abdomen - obesitas derajat I - kemungkinan jalan napas sulit Problem potensial: - gagal intubasi-gagal ventilasi - desaturasi - nyeri pasca operasi Persiapan preoperatif: Informed consent pasien dan keluarga pasien Pasang iv line besar, rehidrasi, pastikan euvolemia Pencegahanaspirasi pneumonia : 30 ml oral non particulated antacid + metocloperamide 10 mg iv + H2 blocker iv Persiapan intubasi sulit: LMA, needle krikotiroidotomi, transtrakeal jet insuflation, fiberoptik/bronkoskopi/video laringoskop (bila ada) Penguji menilai Manajemen anestesi yang dilakukan peserta Pilihan Anestesi : General Anestesi intubasi oral dengan teknik RSI Rencana Tindakan Anestesi : STATICS, menyiapkan obat anestesi yang diperlukan, mengecek mesin anestesi dan alat monitor pasien, memakai alatpelindungdiri (minimal handschoen) Persiapan intubasi sulit: LMA, needle krikotiroidotomi, transtrakeal jet insuflation, fiberoptik/bronkoskopi/video laringoskop (bila ada) Siapkan 3 ukuran ETT: 6,5 ; 7,0 ; 7,5 mm Induksi dengan teknik RSI mengambil laryngoskop dengan tangan kiri, membuka mulut penderita tanpa ekstensi kepala, menyusuri lidah dari kiri ke kanan hingga tampak epiglotis dan plica vocalis3x usaha gagal nyatakan gagal intubasi panggil bantuan, Ventilasi dengan sungkup tidak adekuat desaturasi (SpO2 88%) (pertimbangkan bangunkan pasien, kembalikan ke pernapasan spontan) pasang LMA LMA tidak adekuat pasien desaturasi (SpO2 79%) putuskan emergency invasive airway access needle', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Cedera  Kepala', 'Neuroanestesi', 17,
  'Seorang laki – laki berusia 21 tahun berat badan 50 kg masuk ke IGD dengan keluhan penurunan kesadaran dengan airway tidak clear. Sebelumnya pasien mengalami kecelakaan lalu lintas, dengan kesadaran awal GCS 7 (E2 V3 M2)', 'Lakukan evaluasi preoperative untuk pasien ini!\nTentukan diagnosis kerja usulan pemeriksaan penunjang dan hasil pemeriksaan penunjang kepada penguji dan interprestasikan hasilnya dan pada pasien ini!\nTentukan tatalaksana untuk pasien tersebut!',
  ': Penguji mengamati dan menilai evaluasi preoperatif yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta: Peserta melakukan anamnese : Alergi (-), Medication (-), Past illness (-), Last meal 10 jam sebelum MRS, Event (-) Pasien sempat sadar saat dibawa ke IGD kemudian menjadi tidak sadar (lucid interval). Pemeriksaan fisik : Tekanan Darah 150/90 mmHg, Nadi 46x/mnt, frekuensi napas 10x/mnt, napas berat, irreguler. Kesadaran GCS 7 (E2 V3 M2) Pupil anisokor 4/2 mm. RC +/+ Penguji menilai peserta menegakkan dan menilai pemeriksaan penunjang dan interpretasinya Diagnosis pasien: EDH (Epidural Hematom) Head CT Scan : Epidural hematom Penguji menilai tatalaksana non farmakoterapi pada pasien tersebut : Intubasi endotrakeal: persiapan alat (STATICS) menggunakan handschoen Pasang alat monitor EKG, tensi, pulse oksimeter Test ETT dan alat lain yang diperlukan Silk Manouever memberikan napas bantuan dengan ambubag yang dikoneksikan ke sumber oksigen Induksi Tidak memberikan ventilasi dari saat induksi sampai intubasi mengambil laryngoskop dengan tangan kiri, membuka mulut penderita tanpa ekstensi kepala, menyusuri lidah dari kiri ke kanan hingga tampak epiglotis dan plica vocalis insersi pipa endotrancheal kembangkan cuff, auskultasi untuk simetrisasi suara napas, fiksasi', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Trauma Servikal', 'Neuroanestesi', 17,
  'Seorang laki – laki berusia 27 tahun berat badan 50 kg masuk ke IGD dengan keluhan keempat ekstremitas tidak dapat digerakkan. Sebelumnya pasien mengalami kecelakaan lalu lintas 7 jam yang lalu.', 'Lakukan evaluasi preoperativeuntuk pasien ini serta penanganannya !\nPasien tiba-tiba mengalami penurunan kesadaran, bradikardia, hipotensi, dan hipoventilasi. Tentukan diagnosa yang terjadi pada pasien tersebut dan penatalaksanaannya?\nTentukan tindakan selanjutnya untuk pasien tersebut!',
  ': Penguji mengamati dan menilai initial asessment yang dilakukan peserta danmemberikan hasil pemeriksaan fisik : Primary survey : Airway (A) : clear Breathing (B) : Frekuensi napas 22 x/i, retraksi iga (-), sianosis (-), pernapasan cuping hidung (-), suara napas vesikuler, ronki (-) Circulation (C) : TD = 100/60 mmHg, HR = 60 x/i, teraba halus, akral hangat, temp 37,6 ˚C, SO2 = 97% dengan O2 6 L/i, pasien tidak merasa buang air kecil Dissability (D) : GCS = 9x ( E4 Mx V5 ) E = buka mata spontan, M = tidak dapat dinilai, V = dapat mengenali lingkungan. Pupil isokor ka = ki, diameter = 3mm/3mm, refleks cahaya = +/+ Exposure (E) : terdapat jejas di daerah clavicula atas dan daerah leher bagian belakang Alergi (-), Medication (-), Past illness (-), Last meal 10 jam sebelum MRS, Event (+) Pasien sebelumnya mengalami kecelakaan lalu lintas, mengendarai sepeda motor dengan posisi jatuh daerah kepala terlebih dahulu Penanganan : Pasang colar neck, pasien tetap dalam keadaan in line position (disangkakan trauma servikal), pasang kateter urin, beri analgetik opioid, monitoring hemodinamik Penguji menilai pemeriksaan penunjang dan interpretasinya Foto cervical AP/Lateral : fraktur cervical C5 C6 Head CT scan : Normal Laboratorium : dalam batas normal Setelah peserta menentukan pemeriksaan penunjang. Penguji memberikan data tambahan Data tambahan : Tiba-tiba pasien mengalami penurunan kesadaran, TD : 60/- , HR : 36x/i, RR : 6x/i, retraksi iga (+), pernapasan cuping hidung (+) Penguji menilai diagnosis yang di berikan peserta Diagnosis pasien: Spinal Shock Injury + Fractur C5 C6 Penguji menilai penatalaksanaan yang dilakukan peserta Penatalaksanaan : Airway = jalan nafas harus selalu bebas. Breathing = ventilasi kendali, normokapnia. Pasien dilakukan intubasi dengan prinsip 7P Preparation STATICS Preoxygenation O2 100% Pretreatment Fentanyl 1 – 3 mcg/kgBB, lidokain 1 – 1,5 mg/kgBB Paralysis with induction Positioning Pasien intubasi dengan in line position Placement with proof Post intubation management maintenance sedasi/ analgetik/ relaxan Circulation = target normotensi (hindari lonjakan tekanan darah), cairan isoormoler, normovolemia. Pada pasien terlebih dahulu dilakukan resusitasi cairan 1-2 L cairan RL, pertimbangkan untuk pemberian vasopressor ataupun inotropik. Dilakukan airway management untuk mempertahankan jalan napas. Drugs = teknik yang meningkatkan tekanan intrakranial Environment = pertahankan suhu permisive hipoermia (35oC) Konsul ke bagian bedah syaraf. Perawatan ICU dengan kontrol pernapasan dan pertahankan tekanan darah dengan MAP ≥ 85 mmHg untuk stabilisasi kardiovaskular, pasien tetap dalam keadaan in line position. Pertimbangkan pemakaian compressing device atau pemberian LMWH 3 hari setelah trauma.', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Preeklampsia Berat', 'Anestesi Obstetrik', 17,
  'Seorang Perempuan 29 tahun primi gravida direncanakan SC. Indikasi operasi letak sungsang dengan umur kehamilan 39 minggu. Pasien tidak memiliki riwayat penyakit sebelumnya. Tekanan darahnya saat ANC 8 minggu 120/70 mmHg. Sekarang pasien mengeluh nyeri kepala bagian depan, mual dan kakinya membengkak.', 'Lakukan evaluasi preoperative\nTentukan diagnosis dan persiapan preoperative \nTentukan dan sebutkan Rencana tindakan anestesi \nSebutkan dan tuliskan manajemen paska bedah\nPENILAIAN :\nPenguji mengamati dan menilai tindakan preoperatif yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta.\nPeserta menanyakan :\nAnamnese \nAlergi (-), Medication (-), Past illness (-), Last meal 1 jam sebelum MRS, Event (-)\nnyeri kepala bagian depan, mual dan kakinya membengkak. \nPemeriksaan Klinis: \nBB 92 kg, TB 155 cm.\nKesadaran Compos mentis GCS14 E3V5M6, pupil isokor 3mm/3mm RC +/+\nFrekuensi nafas 18-20 x/menit, suara pernafasan vesikuler suara tambahan tidak ada, \nTekanan darah 170/120 mmHg, Nadi 112 x/menit, kuat, Jantung : suara jantung normal, Suhu 37oC. \nVAS Diam 2/10 cm dan VAS saat HIS 6/10 cm. SaO2 95%.\nAbdomen distensi, defans muscular (+)\nProduksi urine : 50 cc/3 jam\nPemeriksaan penunjang :\nHasil Laboratorium : \nDarah Rutin : Hb 9,8 gr%, Ht 30%, WBC 19 k/µL, Plt 87 gr/dl\nFaal Hemostasis : PPT10,9  (12,2) , APTT 35,8 (30,7), INR 1,5\nBun (Ureum) : 78 mg/dl, Creatinin 2,1 mg/dl\nNa 147 mmol/L, Kalium 5 mmol/L ,Cl 119 mmol/L\nFaal Hati : AST 189, ALT 163, LDH 896, albumin 2,5, globulin 3,42\nGlukosa 98 mg/dl, \nUrinalisa : Berat jenis 1,020; pH 6,5; Protein +4; glukosa +2; Keton +1; eritrosit +2\nThorak foto : belum dikerjakan\nEKG : Sinus Takikardia.\nPenguji menilai Diagnosa dan persiapan preoperative. \nDiagnosa : Preeklapsia Berat + HELLP Syndrome\nPersiapan preoperative : \nKontrol tekanan darah : turunkan tekanan darah 20% dari nilai awal,  target MAP 105 – 125 mm Hg.\nPencegahan kejang : pemberian MgSO4 iv\nIv line besar, persiapan darah\nMonitoring efek samping MgSO4 : frekuensi nafas, produksi urine dan reflek patella dan bila mungkin periksa kadar MgSo4 setidaknya 4 jam setelah memulai terapi MgSo4. Target konsentrasi 4-6 mEq/L.\nMonitoring denyut jantung janin\nPencegahan aspirasi pneumonia : 30 ml oral non particulated  antacid + metocloperamide 10 mg iv + H2 blocker iv\nPenguji menilai Manajemen anestesi yang dilakukan peserta\nPilihan Anestesi : General Anestesi intubasi dengan RSI\nRencana Tindakan Anestesi :\nSTATIC, menyiapkan obat anestesi yang diperlukan, mengecek mesin anestesi dan alat monitor pasien, memakai alat pelindung diri (minimal handschoen)\nPosisi pasien Head Up minimal 30 derajat\nTim operator harus sudah siap dgn drapping pasien\nInduksi dengan agen IV cepat ( propofol / etomidate  ), Muscle relaxan kerja cepat Suksinilkolin 1,5 mg/kgbb atau rocuronium 0,9-1,2 mg/kgbb, bila perlu priming.\nCricoid pressure dengan lembut sebelum induksi ( sellick’s maneuver)\nTidak diberikan ventilasi tekanan positif. \nSiapkan 3 ukuran ETT, memilih pipa endotrakeal dengan ukuran lebih kecil : 6 atau 6,5 mm\nMampu melakukan teknik rumatan anestesi umum dengan 2/3 MAC volatile anestesi\nOpioid diberikan setelah bayi lahir\nPenguji menilai manajemen paska operative yang disebutkan dan ditulis peserta\nPasien di rawat di ICU\nPilihan utama analgesia sistemik opioid intravena menggunakan syringe pump\nBolus parasetamol.\nSebaiknya dihindari penggunaan analgesia epidural karena penderita dengan peningkatan tekanan intracranial dan HELLP syndrome\nSebaiknya tidak diberikan NSAID untuk mencegah terganggunya agregasi trombosit dan juga karena pasien dengan AKI.\nPemberian analgetik opioid intravena.\nPemberian obat antihipertesi',
  ': Penguji mengamati dan menilai tindakan preoperatif yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta. Peserta menanyakan : Anamnese Alergi (-), Medication (-), Past illness (-), Last meal 1 jam sebelum MRS, Event (-) nyeri kepala bagian depan, mual dan kakinya membengkak. Pemeriksaan Klinis: BB 92 kg, TB 155 cm. Kesadaran Compos mentis GCS14 E3V5M6, pupil isokor 3mm/3mm RC +/+ Frekuensi nafas 18-20 x/menit, suara pernafasan vesikuler suara tambahan tidak ada, Tekanan darah 170/120 mmHg, Nadi 112 x/menit, kuat, Jantung : suara jantung normal, Suhu 37oC. VAS Diam 2/10 cm dan VAS saat HIS 6/10 cm. SaO2 95%. Abdomen distensi, defans muscular (+) Produksi urine : 50 cc/3 jam Pemeriksaan penunjang : Hasil Laboratorium : Darah Rutin : Hb 9,8 gr%, Ht 30%, WBC 19 k/µL, Plt 87 gr/dl Faal Hemostasis : PPT10,9 (12,2) , APTT 35,8 (30,7), INR 1,5 Bun (Ureum) : 78 mg/dl, Creatinin 2,1 mg/dl Na 147 mmol/L, Kalium 5 mmol/L ,Cl 119 mmol/L Faal Hati : AST 189, ALT 163, LDH 896, albumin 2,5, globulin 3,42 Glukosa 98 mg/dl, Urinalisa : Berat jenis 1,020; pH 6,5; Protein +4; glukosa +2; Keton +1; eritrosit +2 Thorak foto : belum dikerjakan EKG : Sinus Takikardia. Penguji menilai Diagnosa dan persiapan preoperative. Diagnosa : Preeklapsia Berat + HELLP Syndrome Persiapan preoperative : Kontrol tekanan darah : turunkan tekanan darah 20% dari nilai awal, target MAP 105 – 125 mm Hg. Pencegahan kejang : pemberian MgSO4 iv Iv line besar, persiapan darah Monitoring efek samping MgSO4 : frekuensi nafas, produksi urine dan reflek patella dan bila mungkin periksa kadar MgSo4 setidaknya 4 jam setelah memulai terapi MgSo4. Target konsentrasi 4-6 mEq/L. Monitoring denyut jantung janin Pencegahan aspirasi pneumonia : 30 ml oral non particulated antacid + metocloperamide 10 mg iv + H2 blocker iv Penguji menilai Manajemen anestesi yang dilakukan peserta Pilihan Anestesi : General Anestesi intubasi dengan RSI Rencana Tindakan Anestesi : STATIC, menyiapkan obat anestesi yang diperlukan, mengecek mesin anestesi dan alat monitor pasien, memakai alat pelindung diri (minimal handschoen) Posisi pasien Head Up minimal 30 derajat Tim operator harus sudah siap dgn drapping pasien Induksi dengan agen IV cepat ( propofol / etomidate ), Muscle relaxan kerja cepat Suksinilkolin 1,5 mg/kgbb atau rocuronium 0,9-1,2 mg/kgbb, bila perlu priming. Cricoid pressure dengan lembut sebelum induksi ( sellick’s maneuver) Tidak diberikan ventilasi tekanan positif. Siapkan 3 ukuran ETT, memilih pipa endotrakeal dengan ukuran lebih kecil : 6 atau 6,5 mm Mampu melakukan teknik rumatan anestesi umum dengan 2/3 MAC volatile anestesi Opioid diberikan setelah bayi lahir Penguji menilai manajemen paska operative yang disebutkan dan ditulis peserta Pasien di rawat di ICU Pilihan utama analgesia sistemik opioid intravena menggunakan syringe pump Bolus parasetamol. Sebaiknya dihindari penggunaan analgesia epidural karena penderita dengan peningkatan tekanan intracranial dan HELLP syndrome Sebaiknya tidak diberikan NSAID untuk mencegah terganggunya agregasi trombosit dan juga karena pasien dengan AKI. Pemberian analgetik opioid intravena. Pemberian obat antihipertesi', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Peb', 'Anestesi Obstetrik', 17,
  'Seorang ibu hamil usia 38 tahun, kehamilan keempat, usia kehamilan 35 minggu datang ke rumah sakit untuk periksa kehamilan, karena selama hamil ini kontrol tidak teratur. Riwayat persalinan dahulu melahirkan spontan. Riwayat penyakit dahulu; penyakit kencing manis, asma, alergi obat, darah tinggi disangkal. Pada pemeriksaan fisik keadaan umum baik, overweight, tekanan darah 155/100 mmHg, denyut nadi 114 kali/menit, frekwensi nafas 20 kali/menit, suhu tidak panas, nyeri VAS 4 . Pasien dirawat dan setelah 4 jam diperiksa tekanan darah 180/110 mmHg. Pasien dikonsulkan oleh dokter obsgyn ke dokter anestesi untuk dilakukan seksio sesarea', '1 .Lakukan evaluasi preoperatif dengan kerja sama tim\n2. Tentukan diagnosis dan persiapan preoperatif \n3. Lakukan tehnik anestesi CSE \n4. Monitoring perioperatif\n5. Penatalaksanaan pasca operatif',
  ': Penguji menilai kemampuan peserta melakukan evaluasi preoperatif, komunikasi, edukasi dan kerja sama tim: Penguji mengamati dan menilai peserta melakukan preopvisite: Peserta menanyakan Anamnesa : Alergi (-), Pengobatan (-), Riwayat Penyakit Dahulu (-), Makan Terakhir (4 jam yang lalu), Riwayat penyakit sekarang Menanyakan nyeri; kenceng-kenceng tidak begitu kuat, mual/muntah (-), nyeri kepala (-), pandangan kabur (-), sesak nafas (-) Pemeriksaan fisik: KU : sedang, Kesadaran : komposmentis Vital sign : Tensi 180/110 mmHg, Nadi 114x/menit, Respirasi 20x/menit, Suhu afebris, VAS 4 (nyeri sedang) ketika his Toraks: Paru : Vesikuler (+/+), suara tambahan (-/-) Jantung : irama teratur, bising sistolik (-) Abdomen : perut membesar sesuai usia kehamilan, DJJ 120 -140 Ekstremitas : inferior edema +/+ Pemeriksaan laboratorium: Darah rutin : Hb 10,8 gr%, Ht 32%, WBC 14 k/ul, AT 150.109/L Faal hemostasis: PPT 11,2 (12,2), APTT 32,3 (30,7), INR 0,9 Faal ginjal : BUN 40 mg/dl, Kreatinin 1,2 mg/dl Faal hati : AST 30 IU/L, ALT 40 IU/L, Albumin 2,6, Globulin 3,41 Elektrolit : Na 146 mmo;/L, K 4,6 mmol/L, Cl 110 mmol/L Glukosa : 110 mg/dl Urinalisa : BJ 1,020, pH 6,6, Protein +3 AGD : pH 7,45, PaO2 100 mmHg, PaCO2 38 mmHg, HCO3 23, BE -2, AaDO2 20, SpO2 99% nasal kanul 2 lpm Pemeriksaan penunjang Thorak foto : dalam batas normal EKG : Sinus takikardi 114x/menit 2. Penguji menilai diagnosis dan persiapan preoperatif Diagnosis:', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Preeklamsia Berat Dengan Oedem Pulmo', 'Anestesi Obstetrik', 17,
  'Seorang wanita 24 tahun dikonsul masuk ICU dengan post SC dengan sesak nafas. Riwayat penyakit : pasien post SC emergensi atas indikasi fetal distress 1 jam yang lalu, sebelumya pasien mengeluh sesak nafas sejak 1 hari yang lalu, selama hamil pasien hipertensi dan kedua kaki bengkak. Pemeriksaan fisik saat ini pasien nampak gelisah. Frekuensi napas 35 kali/menit, tensi 170/100 mmHg, nadi 120 kali/menit teraba kuat, akral dingin. Saturasi oksigen 92 % dengan oksigen 12 ltr/mnt NRM. Suhu 36,8 C. Tugas : Lakukan pemeriksaan fisik untuk pasien ini Tentukan prosedur klinis untuk menunjang diagnosis Tentukan diagnosis klinis Lakukan tatalaksana nonfarmakologis dan farmakologis serta monitoring setelah tindakan. Tentukan kemungkinan penyulit atau komplikasi tatalaksana nonfarmakologis dan farmakologis serta antisipasi awal penyulit tersebut.', 'Lakukan tindakan sesuai instruksi penguji.',
  ': Penguji mengamati dan menilai penampilan peserta berdasarkan lembar penilaian penguji menilai kemampuan peserta untuk melakukan pemeriksaan fisis Inspeksi : frekuensi nafas, tanda-tanda distress nafas, rektrasi, sianosis, pernafasan cuping hidung, gelisah palpasi : perkusi : pekak, batas jantung auskultasi : suara nafas kiri kanan, bunyi tambahan Penguji tidak diperbolehkan melakukan interupsi ataupun bertanya kepada peserta selain yang ditentukan Penguji memberitahukan data pemeriksaan fisik dan laboratorium sesuai scenario. Penguji memberikan hasil pemeriksaan penunjang Hb : 9 gr/dl, Lekosit 24.000. Platelet : 120.000/ml3, Proteine uria (+2) AGD : pH : 7.2, PaO2 : 50, PaCO2 : 25, HCO3 : 18, BE: -6 Ronsen thorax : oedem pulmo EKG : Sinus takikardi, 120x, normoaxis Penguji menilai kemampuan diagnosis Diagnosis : Pembacaan AGD : Asidosis metabolik kompensasi alkalosis respiratorik dengan hipoksemia. Diagnosis Klinis : Preeklamsia berat dengan oedem pulmo dengan gagal napas tipe 1 (hipoksemia) Kriteria gagal napas : PaO2 : < 50, PaCO2 > 50 Frekuensi napas > 35, tanda-tanda distres napas Penguji menilai kemampuan peserta ujian dalam tatalaksana nonfarmakologi dan farmakologi Nonfarmakologis : Lakukan intubasi (hanya menyebut, tidak memperagakan) Setting ventilator : Initial setting ventilator : Mode Pressure/volume control ventilation, Predicted body weight : 60 Kg. TV : 360 ml, RR : 12 X/mnt, PEEP : 5, I:E ratio 1:2, FiO2 100%. Penilaian klinis/monitoring setelah setting awal ventilator Fisis : Suara napas, hemodinamik, oksigenasi (saturasi) Farmakologis : Restriksi cairan MgSO4 4g iv loading 15 menit, dilanjutkan 1-3g/jam Anti hipertensi : Nifedipine 3x10 mg Diuretik : Furosemid bolus/syringepump Analgetik post op : NSAID (paracetamol 1gr/ 8jam), fentanyl 0,5 mcg/kgBB/jam (30 mcg/jam) Penguji menilai kemampuan peserta ujian memprediksi kemungkinan penyulit serta antisipasinya. Penyulit/komplikasi : Kejang / eklamsia (terapi MgSO4) Toksisitas MgSo4 (hiporefleks, terapi ca glukonas) Hipotensi (kekurangan cairan dan efek obat, setting ventilator) antisipasi nilai status volume dan pemberian cairan Desaturasi (setting ventilator tidak adekuat, masalah mekanik: ETT, tubing ventilator, endobronkial, lendir, pneumotoraks) antisipasi evaluasi ulang seting ventilator ( TV ekspirasi, PEEP, I:E ratio) Tanda-tanda gagal jantung', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Thorakotomi / Lobektomi', 'Anestesi Umum & Regional', 17,
  'Seorang wanita 50 tahun datang dengan keluhan batuk darah sejak 10 tahun lalu. Batuk darah dirasakan semakin memberat. Pasien telah menjalani terapi OAT selama 9 bulan di puskesmas namun keluhan tidak berkurang. Pasien tidak pernah mengeluh sesak. Kemudian pasien dikonsulkan ke dokter spesialis pulmonologi dan didiagnosis aspergilosis pulmo sinistra. Pasien diberikan terapi antimikosis dan dikonsulkan ke bagian bedah thorak. Pasien diprogram untuk operasi lobektomi inferior pulmo sinistra.', 'Lakukan evaluasi pre anestesi (anamnesis, pemeriksaan fisik, dan pemeriksaan penunjang).\nTegakkan diagnosis pasien dan rencana anestesi pada pasien.\nSebutkan problem pasien dan potensial problem pada pasien\nLakukan intubasi dengan pipa endotrakheal double lumen\nSebutkan komplikasi yang terjadi pada pasien beserta tatalaksananya\nBagaimana manajemen paska operasi pada pasien',
  ': Penguji menilai kemampuan peserta untuk evaluasi pra operasi Anamnesis: A : riwayat alergi / asthma (-) M: Pasien mengkonsumsi anti mikosis dan riwayat pengobatan TB P : Pasien pernah didiagnosa TB paru dengan terapi tuntas L : 6 jam yang lalu E : Batuk darah sejak 10 tahun lalu Pemeriksaan Fisik: B1 : Jalan nafas bebas, malampati 1, gigi ompong (-). RR : 14 x/menit, napas spontan adekuat, retraksi (-). Gerak dada simetris. Suara nafas vesikuler Rh -/+ Wheezing -/- SpO2 97% (oksigen 21%) B2 : nadi teraba kuat frekuensi 64 x/menit , tekanan darah 130/90 mmHg, mukosa mulut basah, turgor normal B3 : Compos mentis, status neurologis normal. B4 : Normal, produksi urin 30 cc / jam B5 : normal B6 : normal Pemeriksaan Penunjang: Darah Rutin : Hb 10 gr%, Ht 30%, WBC 13 k/µL, Plt 250 gr/dl Faal Hemostasis : PPT10,9 (12,2) , APTT 35,8 (30,7) Ureum : 40 mg/dl, Creatinin 1,0 mg/dl Na 135 mmol/L, Kalium 4,2 mmol/L ,Cl 100 mmol/L Faal Hati :AST 40, ALT 30, albumin 2,9 Glukosa 90 mg/dl Analisa gas darah: pH 7,35, PaO2 100 mmHg, PaCO2 44 mmHg, HCO3 24, BE -2, AaDO2 20, SpO2 99% nasal kanul 2 lpm EKG : Normo Sinus Ritme Spirometri : Restriktif Ringan Thorax PA : Gambaran aspergillosis lobus inferior paru sinistra Penguji menilai Diagnosis Dan Problem Aktual – Potensial ditegakkan peserta ujian Diagnosa: Aspergilosis pulmo sinistra pro lobektomi Inferior pulmo sinistra status fisik ASA 2 Problem aktual dan potensial: Restriktif ringan Obstruksi saluran napas bawah Desaturasi Penguji menilai rencana tindakan anestesi yang diusulkan / dikerjakan peserta ujian Anestesi umum napas kendali dengan pipa endotrakheal double lumen Penguji menilai pelaksanaan keterampilan klinis yang diusulkan / dikerjakan peserta ujian Tahapan pemberian anestesi dengan benar dan runut meliputi : Persiapan alat, obat anestesi dan emergensi Monitoring fungsi vital, termasuk EKG, Tekanan darah invasif dengan arterial line, CVC, SpO2, End tidal CO2 Preoksigenasi Induksi iv menggunakan obat sedasi dan obat pelumpuh otot Intubasi dengan ETT double lumen kanan ukuran 35. Dilakukan cek penempatan ETT doble lumen (simulasi ventilasi satu paru) Rumatan anestesi dengan obat agent inhalasi tanpa N2O , narkotik fentanyl 1-2 mcg/kgBB atau morphin 0.1 mg/kgBB, dan obat pelumpuh otot atracurium atau vecuronium atau rocuronium. Rumatan cairan : restriksi cairan dengan prinsip mengganti defisit volume dan cairan rumatan saja. Operasi dimulai dan teknik ventilasi satu paru dilakukan sesuai kebutuhan Saat operasi selesai, diberikan reversal neostigmin dan atropin Anestesi diakhiri, agen inhalasi dihentikan, dan dilakukan penggantian pipa endotrakheal dengan ETT single lumen. Penguji menilai penatalaksanaan pasca operasi yang diusulkan / dikerjakan peserta ujian Tatalaksana pasca operasi: Dirawat di ICU dengan menggunakan ventilator Direncanakan weaning bertahap Manajemen nyeri dengan opioid, pilihan morfin untuk mencegah terjadinya edema pulmo Antimikosis dilanjutkan Penguji menilai Komunikasi, edukasi dan profesionalisme peserta ujian', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Epidural Anestesia', 'Anestesi Obstetrik', 17,
  'Seorang perempuan berusia 18 tahun dengan BB 65 kg, datang ke IGD dengan G1A0P0, hamil 38 minggu dengan pre eklampsia berat. Direncanakan terminasi kehamilan terencana. Sejak 3 minggu terakhir tensi cenderung naik, kaki bengkak, pandangan tidak kabur.', 'Lakukan tindakan sesuai instruksi penguji.',
  'Penguji mengamati dan menilai penampilan peserta berdasarkan lembar penilaian. Penguji memberikan kertas berisi informasi mengenai pasien, yang berisi: Anamnesa: Alergi (-), Medication (-), Past illness (-), Last Meal 1 jam sebelum masuk rumah sakit, Event (-) Pemeriksaan Klinis: BB 65 kg, TB 155 cm. Kesadaran Compos mentis. Frekuensi nafas 24 x/menit, suara pernafasan vesikuler,suara tambahan tidak ada. Tekanan darah 145/90 mmHg, denyut nadi 90 x/menit, kuat. Jantung: suara jantung normal, suhu 37oC. Ekstremitas:oedem. Penguji menjawab hasil pemeriksaan penunjang (hanya jika diminta oleh peserta!) dan menilai interpretasi yang dilakukan oleh peserta uji! Pemeriksaan penunjang: Darah Rutin:Hb 10 gr%, Ht 30%, Trombosit 200.000 Interpretasi:Dalam Batas Normal Faal Hemostasis:PT10,9 (12,2) , APTT 35,8 (30,7), INR 1,5 Interpretasi:Dalam Batas Normal Elektrolit:Na 147 mmol/L, Kalium 5 mmol/L ,Cl 119 mmol/L Interpretasi:Dalam Batas Normal Faal Hati: SGOT: 45, SGPT: 35, LDH: 300 Interpretasi:Dalam Batas Normal Urinalisa:Proteinuria +++ Interpretasi:Pre EklampsiaBerat DJJ:140 x/mnt Interpretasi:Dalam Batas Normal Penguji menilai Diagnosis Dan Problem Aktual–Potensial ditegakkan peserta ujian Problem aktual : Hipertensi Hipovolemia Puasa tidak cukup Problem potensial : Hemodinamik tidak stabil Kejang Aspirasi isi lambung Penguji menilai pelaksanaan tindakan epidural anestesia yang dikerjakan peserta ujian. Prosedur Tindakan Epidural Anestesia: Menyiapkan epidural set, memilih jenis jarum yang sesuai, obat local anestesi danobat emergency serta alat pelindung diri, menyiapkan obat anestesi umum yang diperlukan, mengecek mesin anestesi dan alat monitor pasien Posisi pasien : sitting posisition atau left lateral decubitus Membuat landmark dan menentukan titik penusukan Cuci tangan steril, memakai baju steril dan sarung tangan steril Sterilisasi daerah penusukan, tutup dengan doek lobang steril Infiltrasi lokal anestesi Penusukan jarum epiduralpadatitik yang ditentukan, identifikasi Loss Of Resistance (LOR )dengan spuit berisi cairan NaCl 0.9% atau vakum udara Masukkan kateter epidural dan jarum dicabut. Fiksasi catheter Test dose', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Spinal Anestesia', 'Anestesi Umum & Regional', 20,
  'Seorang laki-laki umur 25 tahun dengan BB 60 Kg mengalami kecelakaan lalu lintas. Masuk Ke IGD dengan fraktur tertutup kruris Sinistra, akan dilakukan tindakan ORIF. Tidak terdapat cedera kepala. Riwayat kesehatan sebelumnya baik.', 'Lakukan visit preoperatif terhadap pasien tersebut\nSebutkan problem aktual dan problem potensial terhadap pasien tersebut\nLakukan tindakan spinal anestesi pada pasien tersebut.',
  ': Penguji mengamati dan menilai tindakan preoperatif yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta. Peserta melakukan Primary Survey Airway : Clear, C-spine stabil Breathing: Spontan, RR 18x/mnt, SP vesikuler; Suara tambahan Tidak dijumpai Circulation: Akral Hangat, merah, kering; TD : 110//70 mmHg Disability: Sensorium GCS 15; pupil isokor kanan=kiri; diameter 3 mm : 3 mm Exposure: Fraktur tertutup kruris sinistra Peserta menanyakan Anamnese Alergi (-), Medication (-), Past illness (-), Last meal 1 jam sebelum masuk rumah sakit, Event (-) Jatuh dari sepeda motor kaki kiri sakit kalau digerakkan. Riwayat penyakit dahulu :tidak pernah sakit yang serius. Pemeriksaan Klinis Kesadaran Compos mentis. Frekuensi nafas 18 x/menit, suara pernafasan vesikule rsuara tambahan tidak ada Tekanan darah 120/78 mmHg, Nadi 76 x/menit, kuat, Jantung :suara jantung normal, Suhu 37oC. VAS Diam 3 dan bergerak 8 (pada skala 1 - 10 cm) . Pemeriksaan penunjang Hasil Laboratorium : Darah Rutin :Hb 10 gr%, Ht 30% Leukosit 9000, trombosit 257.000 Faal Hemostasis : PT10.9(12.2), APTT 35.8 (30.7), INR 1.5 Na 137 meq/L, Kalium 4.5 meql/L,Cl 119 mmol/L Faal Hati : normal Glukosa : 98 mg/dl. Penguji menilai problem potensial Problem aktual Nyeri Perdarahan Potensial problem : Blok Spinal tinggi Nyeri Paska anestesi 3. Penguji menilai keterampilan tindakan anestesi yang dilakukan peserta Teknik Anestesi Menyiapkan spinal set, memilih jenis jarum spinal yang sesuai, obat regional anestesi danobat emergensi serta alat pelindung diri, menyiapkan obat anestesi umum yang diperlukan, mengecek mesin anestesi dan alat monitor pasien. Posisi pasien : posisi duduk Left lateral decubitus, sebelumnya diberikan analgesia. Membuat landmark dan menentukan titik puncture. Cuci tangan steril, memakai baju steril dan handschoen. Sterilisasi daerah puncture, tutup dengan duk lobang steril. Infiltrasi lokal anestesi. Puncture spinal anestesi sampai keluar LCS . Barbotase dan memasukkan obat lokal Anestesi. Memposisikan pasien kembali. Menilai keberhasilan blok dengan pinprick dan bromage scale. Penguji menilai komunikasi,edukasi serta perilaku profesionalisme peserta. Memperkenalkan diri kepada keluarga pasien, dengan menyebutkan nama dan bidang keahlian. Memberikan informasi kepada pasien serta keluarga pasien dengan rasa hormat, tentang keadaan umum pasien, rencana tindakan operasi yang akan dilakukan, pemeriksaan laboratorium dan radiologi untuk penilaian sebelum dilakukan tindakan anestesi dan operasi Memberikan penjelasan kepada keluarga pasien secara lengkap tentang rencana tindakan spinal anestesi, problem yang mungkin timbul pada saat atau paska tindakan operasi, serta memberikan penjelasan tentang efek samping maupun resiko yang dapat timbul. Melakukan tindakan dengan memperhatikan kenyamanan pasien.', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'CSE (Continous Spinal Epidural Anesthesia)', 'Anestesi Umum & Regional', 20,
  'Dikonsulkan seorang perempuan berusia 65 tahun berat badan 65 kg diantar ke IGD dengan keluhan tidak bisa berjalan setelah jatuh di kamar mandi. Kaki kanan sakit bila digerakkan. Sebelumnya pasien sehat, tidak ada riwayat hipertensi. Pasien ditangani sejawat ortopaedi. Setelah dilakukan pemeriksaan radiologis didiagnosa fraktur collum femur pasien dipondokkan untuk operasi AMP.', 'Lakukan evaluasi preoperative\nTentukan diagnosis dan persiapan preoperative \nTentukan dan sebutkan Rencana tindakan anestesi \nSebutkan dan tuliskan manajemen paska bedah',
  ': Penguji mengamati dan menilai tindakan preoperatif yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta. Peserta menanyakan : Anamnese Alergi (-), Medication (-), Past illness (-), Last meal 1 jam sebelum MRS, Event (-) Jatuh di kamar mandi, tidak bisa jalan, kaki kanan sakit bila digerakkan. Riwayat penyakit dahulu : pasien kalau jalan agak jauh napas terasa berat. Pemeriksaan Klinis: BB 65 kg, TB 155 cm. Kesadaran Compos mentis GCS14 E3V5M6, pupil isokor 3mm/3mm RC +/+ Frekuensi nafas 18-24 x/menit, suara pernafasan vesikuler suara tambahan tidak ada, Tekanan darah 150/90 mmHg, Nadi 112 x/menit, kuat, Jantung : suara jantung normal, Suhu 37oC. VAS Diam 4/10 cm dan. SaO2 95%. Abdomen distensi, defans muscular (+) Produksi urine : 50 cc/3 jam Pemeriksaan penunjang : Hasil Laboratorium : Darah Rutin : Hb 9,8 gr%, Ht 30%, WBC 19 k/µL, Plt 87 gr/dl Faal Hemostasis : PPT10,9 (12,2) , APTT 35,8 (30,7), INR 1,5 Bun (Ureum) : 78 mg/dl, Creatinin 2,1 mg/dl Na 147 mmol/L, Kalium 5 mmol/L ,Cl 119 mmol/L Faal Hati : AST 189, ALT 163, LDH 896, albumin 2,5, globulin 3,42 Glukosa 98 mg/dl, Urinalisa : Berat jenis 1,020; pH 6,5; Protein +4; glukosa +2; Keton +1; eritrosit +2 Thorak foto : belum dikerjakan EKG : Sinus Takikardia. Penguji menilai Diagnosa dan persiapan preoperative. Diagnosa : Fraktur colum femur pro AMP dengan penyulit cardio Persiapan preoperative : Kontrol tekanan darah : Pencegahan nyeri : immobilisasi dan pemberian analgetika. Iv line besar. Monitoring hemodinamik. Penatalaksanaan nyeri paska operasi. Penguji menilai Manajemen anestesi yang dilakukan peserta Pilihan Anestesi : continues spinal epidural anestesi. Rencana Tindakan Anestesi : STATIC, menyiapkan obat anestesi yang diperlukan, mengecek mesin anestesi dan alat monitor pasien, Menyiapkan spinal set, obat RA dan obat emergency serta alat pelindung diri. Posisi pasien : left lateral decubitus, sebelumnya diberikan analgesi. Membuat landmark dan menentukan titik puncture. Cuci tangan steril.I memakai baju steril dan handschoen. Sterilisasi daerah puncure, dreping. Infiltrasi lokal anestesi. Puncture epidural dengan LOR NaCl atau udara. Pemasangan alat fiksasi, puncture jarum spinal dan injeksi obat. Pemasangan epidural catheter. Fixasi Carheter', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
  scenario = EXCLUDED.scenario, instructions_participant = EXCLUDED.instructions_participant,
  instructions_examiner = EXCLUDED.instructions_examiner, rubric = EXCLUDED.rubric,
  equipment = EXCLUDED.equipment, updated_at = now();

INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Pemasangan CVC Subklavia', 'Resusitasi & Critical Care', 17,
  'Seorang pria dewasa usia 60 tahun datang ke UGD rujukan puskesmas dengan peritonitis dengan syok. Tanda vital : TD 70/30, N 140 x/m, suhu 39,5oC, rr 28x/mnt. Tugas : Lakukan informed consent pada pasien/ keluarga tentang tindakan pemasangan CVC subclavia Lakukan tindakan pemasangan CVC subclavia PENILAIAN Kandidat melakukan: Cuci tangan Pakai handscoen Disinfeksi Tutup dengan doek steril Landmark dan posisi pasien utk memudahkan insersi CVC Kandidat melakukan dengan lengkap dan urut 7 hal dari : Infiltrasi lokal anestesi Insersi jarum CVC Aspirasi darah Memasukkan wire Dilatasi Memasukkan CVC (mempertahankan posisi wire) Mengambil wire Tes aspirasi Fixasi Sambungkan dengan infus set Evaluasi cvc paska pemasangan dengan foto thorax', 'Lakukan tindakan sesuai instruksi penguji.',
  'Kandidat melakukan: Cuci tangan Pakai handscoen Disinfeksi Tutup dengan doek steril Landmark dan posisi pasien utk memudahkan insersi CVC Kandidat melakukan dengan lengkap dan urut 7 hal dari : Infiltrasi lokal anestesi Insersi jarum CVC Aspirasi darah Memasukkan wire Dilatasi Memasukkan CVC (mempertahankan posisi wire) Mengambil wire Tes aspirasi Fixasi Sambungkan dengan infus set Evaluasi cvc paska pemasangan dengan foto thorax', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
