INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'EGDT Dan CVC', 'Resusitasi & Critical Care', 17,
  'Seorang laki-laki usia 40 tahun BB 50 Kg datang ke IGD rujukan puskesmas dengan keluhan nyeri perut. Dari pemeriksaan fisik kesadaran apatis, frekwensi nafas 28x/menit, SP bronchial; ST ronchi kering, dengan non rebreathing mask 8 liter/menit, tekanan darah 70/40 mmHg, Nadi 140 x/menit,Temperature390 C. Pasien di diagnosa septik syok et causa peritonitis.', 'Sebutkan tahapan EGDT\nLakukan tindakan',
  'Pastikan identitas peserta ujian. Amati dan berikan skor sesuai rubrik penilaian.', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
