INSERT INTO public.osce_stations (user_id, title, category, duration_minutes, scenario, instructions_participant, instructions_examiner, equipment, rubric)
VALUES (
  NULL, 'Chronic Kidney Disease Dengan Pemasangan Hemodialisa Catheter', 'Resusitasi & Critical Care', 17,
  'Seoranglaki-laki 50tahun datang ke UGD dengan keluhan sesak nafas sejak 1 jam SMRS dan bertambah beratdan bengkak di wajah dan kedua kaki dan tangan. dengan riwayat penyakit dahulu : riwayat penyakit ginjal.', 'Lakukan evaluasi preoperatif .\nTentukan diagnosis, problem aktual-potensial, dan persiapan  preoperatif .\nTentukan rencana tindakan, indikasi, tindakan tersebut',
  ': Penguji mengamati dan menilai evaluasi preoperatif yang dilakukan peserta dan memberikan hasil pemeriksaan fisik dan pemeriksaan penunjang bila diminta oleh peserta. Peserta menanyakan : Anamnesa A : alergi: (-) M: Medikasi: (-) P: Past illness: (-) L: last meal: 6 jam SMRS E: event: sesak nafas PemeriksaanKlinis: BB 85 kg, TB 160 cm, BMI 33,2 kg/m2 Kesadaran Compos mentis GCS15 E4V5M6 A: buka mulut 2 jari, malampati 2, leher pendek, TMD < 6 cm, gerak leher bebas. B: RR: 30x/menit SpO2: 94% udara bebas, suara dasar vesikuler di kedua lapang paru, rbk+/+, rbh +/+ C: Tekanandarah 193/72 mmHg, Nadi102 x/menit, kuat, Jantung : suarajantung normal, batas jantung kiri bawah SIC VI 3 cm lateral Linea midclavicular sinistra. Suhu 37,4oC, CRT < 2 detik Mata: konjungtiva anemis (+/+) Abdomen:supel, nyeri tekan(-), defans (-) Ekstremitas: pitting oedem ekstremitas superior et inferior Produksi urine : 10 cc/jam Pemeriksaanpenunjang : Hb: 7,8 Ht: 23,6 Lekosit: 25,8 Eritrosit: 1,5 Trombosit: 261 Albumin: 2,7 Pt: 14,1 Aptt: 36,7 Inr : 1,100 Natrium : 135 Kalium: 6,4 Clorida: 109 Ureum: 105 Kreatinin : 14 AGD: pH : 7,258 BE : -5,9 PCO2 50,4 Po2 97,1 Hco3 16,5 TCO2 21,9 O2 saturasi:95 Thorakfoto : CTR>50% , tampak oedem pulmo, corakan bronkovaskular meningkat EKG : Sinus takikardi HR 108, hipertrofi ventrikel kiri Diagnosis, problem aktual – potensial, persiapan preoperatif Diagnosis anestesiologi: laki-laki, 50 tahun obesitas, dengan gagal ginjal kronis dan oedem pulmo, asidosis respiratorik mixed metabolik pro cito hemodialisa (di ruang operasi) Problem aktual: - gagal ginjal kronis - obesitas derajat I - kemungkinan jalan napas sulit - oedem pulmo - asidosis respiratorik mixed metabolik Problem potensial: - gagal pemasangan hd cath - desaturasi Persiapan preoperatif: Informed consent pasien dan keluarga pasien Pasang iv line mikro, Persiapan pemasangan hd cath, alat, obat emergency, Penguji menilai indikasi pemasangan kateter hemodialisa Indikasi absolute Keadaan umum buruk dan gejala klinisnya nyata seperti mual, dan muntah, diare Perikarditis uremik Ensefalopati atau neuropati uremik Udem paru akut dengan overhydration refrakter terhadap Diuretika (tidak bisa ditanggulangi dengan obat diuretika) Kreatinin >10mg % Ureum darah lebih > 200 mg/dl atau kenaikan ureum darah lebih dari 100 mg/dl per hari (hiperkatanolisme) Hiperkalemia (K serum > 6mEq/L) Asidosis dengan bikarbonat serum kurang dari 10 mEq/L atau pH < 1,75 Anuria berkepanjangan (>5 hari Penguji menilai ketrampilan pemasangan HD cath yang dilakukan peserta Rencana Tindakan Anestesi : STATICS, menyiapkan obat anestesi yang diperlukan, mengecek mesin anestesi dan alat monitor pasien, memakai alatpelindung diri (minimal handschoen) Persiapan intubasi sulit: LMA, needle krikotiroidotomi, transtrakeal jet insuflation, fiberoptik/bronkoskopi/video laringoskop (bila ada) Siapkan 3 ukuran ETT: 6,5 ; 7,0 ; 7,5 mm Siapkan alat HD cath dan obat emergency, Posisikan pasien dalam keadaan berbaring, bila masih sesak dapat diposisikan pasien dalam keadaan head up 30 derajat. Lakukan ganjal pada bahu kanan atau bahu kiri pasien Operator melakukan cuci steril dan memakai baju steril Lakukan tindakan aseptik dan antiseptik pada daerah subclavia kanan Tutup dengan doek steril Lakukan tindakan lokal anestesi pada daerah puncture Tusuk dengan jarum 18 G ke arah antitragus kontralateral ataupun ke arah jugular notch, hingga teraspirasi darah vena , masukkan guide wire, perlebar insersi dengan mess, cabut jarum 18 G, perlebar dengan dilator Masukkan kateter hd cath dengan gentle. Tarik guide wire, aspirasi darah vena dari kedua lumen, dengan menggunakan nacl 500 ml dan heparin 5000 iu. Pastikan aliran kedua lumen lancar. Tutup kedua lumen Fiksasi kateter hd cath dengan hecting. Tutup dengan kasa steril. Pemasangan hd cath selesai Lakukan foto thoraks PA post pemasangan Kateter Hemodialisa Cover | ............................................................................. | 1 Daftar Isi | .............................................................................. | 2 Komponen Penilaian OSCE | ............................................................................. | 3 Anestesia Pada Prosedur Invasif Minimal | ............................................................................. | 5 Laparoskopi Appendiktomi.............................. | 11 Pneumothorax Ec Laparoscopy...................... | 13 Anestesia Pada Endokrin | ............................................................................. | 16 Total Tyroidektomi.............................................. | 20 Hipertiroid Pada Operasi Darurat /Ngt........... | 22 Manajemen Penyulit Pediatrik | ............................................................................. | 25 Manajemen Anestesi Pediatrik........................ | 28 Anestesi Umum Pada Labiopalatoschizis....... | 31 HIL Dupleks......................................................... | 33 Terapi Intensif | ............................................................................. Gagal Nafas + Syok Kardiogenik..................... | 35 Urologi | .............................................................................. TURP..................................................................... | 37 Anestesia Bedah Rawat Jalan / Luar Kamar Bedah | .............................................................................. Tumor Payudara................................................ | 39 Kegawatdaruratan | ............................................................................. | 41 Trauma Dan Emergensi..................................... | 44 Gagal Nafas....................................................... | 46 Ketoasidosis Diabetik........................................ | 48 Manajemen Penyulit Kegawatdaruratan...... | 51 Krikotiroidotomi.................................................. | 54 Neuroanestesi | ............................................................................. Cedera Kepala................................................. | 57 Trauma Servikal.................................................. | 59 Obstetri | ............................................................................. Preeklampsia Berat........................................... | 61 PEB...................................................................... | 64 Preeklamsia Berat Dengan Oedem Pulmo... | 67 Anestesia Pada Prosedur Bedah Thorak | .............................................................................. Thorakotomi / Lobektomi.................................. | 69 Anestesia Regional Dan Manajemen Nyeri | .............................................................................. Epidural Anestesia.............................................. | 72 Spinal Anestesia................................................. | 74 CSE (Continous Spinal Epidural Anesthesia).. | 76 Pemasangan Cvc | ............................................................................. Pemasangan CVC Subklavia........................... | 78 EGDT dan CVC................................................... | 79 Chronic Kidney Disease Dengan Pemasangan Hemodialisa Catheter............. | 81', ARRAY['Manekin simulasi', 'Alat monitoring standar'], '[{"aspect": "Evaluasi Pra Anestesi", "weight": 2, "items": ["Melakukan anamnesis AMPLE lengkap", "Melakukan pemeriksaan fisik klinis", "Melakukan pemeriksaan penunjang"]}, {"aspect": "Problem Aktual dan Potensial", "weight": 2, "items": ["Menentukan problem aktual", "Menentukan problem potensial"]}, {"aspect": "Keterampilan Klinis", "weight": 3, "items": ["Melakukan persiapan alat dan obat", "Melakukan tindakan prosedur anestesi dengan benar", "Melakukan monitoring dan penanganan penyulit"]}, {"aspect": "Komunikasi dan Perilaku Profesional", "weight": 1, "items": ["Meminta izin secara lisan", "Melakukan tindakan dengan berhati-hati", "Memperhatikan kenyamanan pasien"]}]'::jsonb
) ON CONFLICT (title) DO UPDATE SET
